'use strict';
/**
 * UWorld Buzz Fun — Cardiology.
 *
 * One card per UWorld Adventure cardiology question (421, CA-005 … CA-696),
 * cut down to the one concept it tests. Written in our own words — no stem or
 * explanation text is copied. Same rules as the other UWorld decks: the answer
 * matches the wrong answers in style and length, and the explanation is three
 * full sentences.
 *
 * Row: [sourceId, type, topic, clue, answer, [3 wrong answers], [points]]
 * Card id is BFU-<sourceId> (CA-nnn). Run `node server/buzzfun/check.js`.
 */
module.exports = [
  ["CA-005","ASSOCIATION","Cardiomyopathy & tumors","Heart transplant two weeks ago, new exertional dyspnea — biopsy finding of acute rejection","Dense interstitial lymphocytic infiltrate",["Concentric coronary intimal thickening","Perivascular eosinophil-rich infiltrate","Scant cells with interstitial fibrosis"],["Acute cellular rejection usually appears weeks to months after transplant and is diagnosed on endomyocardial biopsy.","Recipient T cells sensitised to donor HLA invade the graft, giving a dense interstitial lymphocytic infiltrate with myocyte damage.","Concentric intimal thickening of the coronaries is chronic rejection (cardiac allograft vasculopathy), which develops over years."]],
  ["CA-006","MECHANISM","Cardiac physiology","Pressure–volume loop widens leftward after a positive inotrope — which value rises?","Stroke volume",["End-systolic volume","End-diastolic pressure","Afterload"],["A positive inotrope makes the ventricle squeeze harder, so it empties further and end-systolic volume falls.","With the same filling, a smaller end-systolic volume means a wider loop and a larger stroke volume.","Ejection fraction rises too, while preload and afterload stay about the same."]],
  ["CA-007","ASSOCIATION","Cardiac physiology","Long-standing hypertension; soft sound just before S1, heard at the apex in left lateral decubitus","Left ventricular hypertrophy",["Mitral valve prolapse","Dilated left ventricle","Pericardial effusion"],["A sound just before S1 is an S4, made by the atrium contracting into a stiff ventricle.","Years of high blood pressure thicken the left ventricle, which reduces its compliance.","An S4 is always abnormal and is never heard in atrial fibrillation, because it needs an atrial kick."]],
  ["CA-008","ASSOCIATION","Valves & endocarditis","Injection drug user, S. aureus bacteremia, cavitating lung nodules — where is the valve best heard?","Left lower sternal border",["Right upper sternal border","Left upper sternal border","Cardiac apex"],["Injection drug use seeds the right heart, so S. aureus tricuspid endocarditis is classic.","Septic emboli from the tricuspid valve lodge in the lungs as multiple cavitating nodules.","The tricuspid valve is heard best at the left lower sternal border, in the 4th or 5th intercostal space."]],
  ["CA-009","ASSOCIATION","Cardiac physiology","Endurance athlete vs sedentary peer: ejection fraction, LV cavity and peak cardiac output","Same EF, larger cavity, higher peak output",["Higher EF, same cavity, same peak output","Lower EF, larger cavity, higher peak output","Same EF, smaller cavity, higher peak output"],["Endurance training causes eccentric hypertrophy, enlarging the left ventricular cavity.","Ejection fraction stays normal, but each beat moves more blood, so resting heart rate falls.","Peak cardiac output is higher because maximum stroke volume is larger."]],
  ["CA-010","MECHANISM","Cardiac physiology","Treadmill test: HR and mean BP both rise — which value falls at peak exercise?","Total peripheral resistance",["Pulse pressure","Venous return","Myocardial oxygen use"],["During exercise, metabolites (adenosine, K⁺, CO₂, lactate) dilate arterioles in working muscle.","This local vasodilation lowers total systemic vascular resistance even as cardiac output rises.","Mean arterial pressure still rises modestly because cardiac output increases more than resistance falls."]],
  ["CA-011","ASSOCIATION","Ischemic heart disease","Teenager's autopsy: flat yellow streaks inside the aorta — predominant cell","Macrophages",["Neutrophils","Smooth muscle cells","Fibroblasts"],["Fatty streaks are the earliest lesion of atherosclerosis and can appear in childhood.","They are made mostly of lipid-laden macrophages called foam cells.","Smooth muscle proliferation and a fibrous cap come later, in the fibrous plaque."]],
  ["CA-012","MECHANISM","Vascular disease","Hair stylist with aching legs, dilated tortuous leg veins and brown skin changes — the abnormality lies in","Venous valves",["Arterial intima","Lymphatic channels","Capillary endothelium"],["Varicose veins form when venous valves fail and blood pools in superficial veins.","Long periods of standing raise venous pressure and worsen valve failure.","Chronic venous hypertension causes stasis dermatitis, hemosiderin staining and ulcers near the medial ankle."]],
  ["CA-013","ASSOCIATION","Pericardium","Korotkoff sounds heard only in expiration at 120 mm Hg but throughout at 100 mm Hg — think","Pericardial disease",["Aortic regurgitation","Hypertrophic cardiomyopathy","Aortic stenosis"],["A fall in systolic pressure of more than 10 mm Hg on inspiration is pulsus paradoxus.","In tamponade, inspiration fills the right ventricle, which bulges the septum and limits left ventricular filling.","Pulsus paradoxus is also seen in severe asthma, COPD and constrictive pericarditis."]],
  ["CA-014","MECHANISM","Heart failure & shock","Smoker with wheeze, prolonged expiration and hyperinflation — what gives the fastest relief?","cAMP buildup in airway smooth muscle",["cGMP buildup in vascular smooth muscle","Calcium influx into airway smooth muscle","Leukotriene receptor blockade in airways"],["This is an acute exacerbation of obstructive lung disease, not heart failure.","Inhaled β2 agonists activate Gs, raising cAMP and relaxing bronchial smooth muscle within minutes.","Leukotriene blockers and steroids act too slowly to give immediate relief."]],
  ["CA-015","ASSOCIATION","Heart failure & shock","Confused, hypotensive: high cardiac output, low wedge pressure, low SVR, high mixed venous O₂","Bacterial infection",["Massive hemorrhage","Acute MI","Cardiac tamponade"],["Low systemic vascular resistance with high cardiac output is the pattern of distributive shock.","Sepsis, usually bacterial, is the most common cause of distributive shock.","Mixed venous oxygen is high because blood bypasses tissues and cells extract oxygen poorly."]],
  ["CA-016","MECHANISM","Hypertension","Hypertensive emergency with rising creatinine — IV arteriolar dilator that also boosts renal flow and natriuresis","Fenoldopam",["Nitroprusside","Hydralazine","Nicardipine"],["Fenoldopam is a dopamine D1 receptor agonist.","D1 activation dilates arterioles, especially renal ones, so renal blood flow and sodium excretion rise.","It is useful in hypertensive emergency when kidney function is worsening."]],
  ["CA-017","SIDE_EFFECT","Ischemic heart disease","Inferior STEMI at a rural hospital; pain eases and a brief harmless ventricular rhythm appears — which drug reperfused?","Alteplase",["Heparin","Aspirin","Metoprolol"],["Without access to PCI, a STEMI is treated with a fibrinolytic such as alteplase.","Alteplase converts plasminogen to plasmin, which dissolves the fibrin clot.","Accelerated idioventricular rhythm after relief of pain is a marker of successful reperfusion."]],
  ["CA-018","ASSOCIATION","Anatomy","Penetrating wound at the left sternal border, 4th intercostal space — which chamber is hit?","Right ventricle",["Left ventricle","Left atrium","Right atrium"],["The right ventricle forms most of the anterior surface of the heart.","A stab wound at the left sternal border in the 4th intercostal space therefore usually enters the right ventricle.","The left atrium is the most posterior chamber, lying against the esophagus."]],
  ["CA-019","MECHANISM","Cardiac drugs","New AF drug: QRS normal at rest but widens only at high heart rates — which agent?","Flecainide",["Lidocaine","Amiodarone","Sotalol"],["Class IC drugs bind sodium channels tightly and release them very slowly.","At fast heart rates the drug has less time to unbind, so sodium block builds and the QRS widens (use dependence).","Flecainide is avoided in structural heart disease because it can be proarrhythmic."]],
  ["CA-020","ASSOCIATION","Congenital & fetal","Leg DVT on heparin, then a sudden MCA stroke — expected heart finding","Wide, fixed splitting of S2",["Holosystolic murmur at apex","Continuous machinery murmur","Paradoxical splitting of S2"],["A venous clot that causes a stroke has crossed from right to left, a paradoxical embolism.","An atrial septal defect or patent foramen ovale allows this crossing.","An atrial septal defect causes wide, fixed splitting of S2 that does not change with breathing."]],
  ["CA-021","ASSOCIATION","Pericardium","After a viral illness: chest pain and low-voltage QRS that alternates in height — chest x-ray?","Enlarged globular heart, clear lungs",["Normal heart with Kerley B lines","Boot-shaped heart, dark lungs","Egg-on-a-string heart shape"],["Low voltage with beat-to-beat variation (electrical alternans) means a large pericardial effusion.","The heart swings within the fluid, changing its electrical axis each beat.","The x-ray shows a water-bottle (globular) cardiac silhouette with clear lung fields."]],
  ["CA-022","ASSOCIATION","Cardiac physiology","Catheter tracing 25/2 mm Hg, then 25/10 mm Hg further on — where was the first reading?","Right ventricle",["Right atrium","Pulmonary artery","Left atrium"],["The right ventricle has a systolic pressure about 25 mm Hg and a diastolic pressure near zero.","In the pulmonary artery the systolic pressure is the same, but the pulmonic valve keeps diastolic pressure near 10 mm Hg.","A rise in diastolic pressure as the catheter advances marks the step from ventricle to artery."]],
  ["CA-023","ASSOCIATION","Cardiomyopathy & tumors","Young athlete collapses and dies during a match after exertional chest pain — autopsy shows","Myocyte hypertrophy with patchy fibrosis",["Fatty replacement of right ventricle","Coronary plaque with fresh thrombus","Lymphocytic myocarditis"],["Hypertrophic cardiomyopathy is the commonest cause of sudden cardiac death in young athletes.","It is usually autosomal dominant, from mutations in sarcomere genes such as β-myosin heavy chain.","Histology shows disarrayed, hypertrophied myocytes with interstitial fibrosis, the substrate for ventricular arrhythmia."]],
  ["CA-024","MECHANISM","Cardiac drugs","Why does verapamil relax vessels and weaken the heart but spare skeletal muscle?","Little need for extracellular Ca²⁺ influx",["Few L-type channels in the sarcolemma","Rapid metabolism of drug in muscle","Calcium release only via IP₃"],["Cardiac and smooth muscle need Ca²⁺ to enter through L-type channels to trigger contraction.","Skeletal muscle uses a mechanical link between the DHP receptor and the ryanodine receptor to release stored Ca²⁺.","Blocking calcium entry therefore has little effect on skeletal muscle force."]],
  ["CA-025","ASSOCIATION","Heart failure & shock","Days of worsening breathlessness, orthopnea, BP 162/86, chest x-ray with interstitial fluid and effusions","Acute decompensated heart failure",["Acute exacerbation of COPD","Community-acquired pneumonia","Acute pulmonary embolism"],["Progressive dyspnea with orthopnea suggests fluid in the lungs from a failing left ventricle.","The x-ray shows interstitial edema, Kerley B lines, cephalization and pleural effusions.","Treatment centres on loop diuretics and lowering preload and afterload."]],
  ["CA-026","ASSOCIATION","Vascular disease","Sudden painless monocular vision loss, cherry red spot, carotid bruit — the embolus took which route?","Internal carotid → ophthalmic → retinal",["External carotid → facial → retinal","Vertebral → basilar → retinal","Internal carotid → middle cerebral → retinal"],["A cherry red spot with retinal whitening is central retinal artery occlusion.","Emboli from carotid plaque travel up the internal carotid into its first branch, the ophthalmic artery.","The central retinal artery is a branch of the ophthalmic artery."]],
  ["CA-027","MECHANISM","Cardiac physiology","Ventricular myocyte action potential: ions for upstroke, plateau and repolarisation in order","Sodium, calcium, potassium",["Calcium, sodium, potassium","Sodium, potassium, calcium","Potassium, calcium, sodium"],["Phase 0 is a rapid inward sodium current through voltage-gated channels.","Phase 2, the plateau, is calcium entering through L-type channels balanced by potassium leaving.","Phase 3 repolarisation is driven by outward potassium current."]],
  ["CA-028","ASSOCIATION","Congenital & fetal","Pulse felt along the medial border of the sternocleidomastoid — derived from which aortic arch?","Third",["Fourth","Sixth","Second"],["The pulse beside the sternocleidomastoid is the common carotid artery.","The common carotid and proximal internal carotid come from the third aortic arch.","The fourth arch forms the aortic arch and right subclavian, and the sixth forms the pulmonary arteries and ductus."]],
  ["CA-029","ASSOCIATION","Arrhythmias","Teen with sudden racing heart; resting ECG has a short PR and a slurred QRS upstroke","Accessory atrioventricular pathway",["Re-entry inside the AV node","Ectopic focus in the atrium","Blocked right bundle branch"],["A short PR interval and delta wave mean Wolff-Parkinson-White pattern.","The bundle of Kent bypasses the AV node, pre-exciting part of the ventricle.","It predisposes to reentrant tachycardia; AV nodal blockers are avoided if atrial fibrillation conducts down the pathway."]],
  ["CA-030","ASSOCIATION","Valves & endocarditis","Diastolic murmur for years, then a stroke; thickened mitral leaflets fused at the commissures","Rheumatic fever",["Infective endocarditis","Myxomatous degeneration","Age-related calcification"],["Mitral stenosis with commissural fusion is almost always a late result of rheumatic fever.","Molecular mimicry between group A strep M protein and cardiac tissue causes the original damage.","A dilated left atrium in mitral stenosis promotes atrial fibrillation and clots that cause stroke."]],
  ["CA-031","MECHANISM","Hypertension","Elderly man with high systolic but normal diastolic pressure — age-related cause","More collagen in the arterial wall",["More renin from the kidney","Thicker left ventricular wall","More sodium retained by kidney"],["Isolated systolic hypertension is the commonest form of hypertension in older adults.","With age, collagen replaces elastin in the aorta, making it stiff.","A stiff aorta raises systolic pressure and widens pulse pressure, while diastolic pressure stays low or normal."]],
  ["CA-032","MECHANISM","Hypertension","Hypertensive emergency: IV drug lowers SVR and heart rate while stroke volume stays the same","Labetalol",["Hydralazine","Nitroprusside","Esmolol"],["Labetalol blocks both α1 and β receptors.","α1 blockade lowers vascular resistance, and β1 blockade prevents the reflex rise in heart rate.","Pure vasodilators like hydralazine instead cause reflex tachycardia."]],
  ["CA-033","ASSOCIATION","Ischemic heart disease","Proximal RCA occlusion: BP 70/60, distended neck veins, clear lungs — hemodynamics","Low CO, low wedge, high CVP",["Low CO, high wedge, high CVP","High CO, low wedge, low CVP","Low CO, low wedge, low CVP"],["Proximal right coronary occlusion can infarct the right ventricle.","A failing right ventricle backs blood up into the veins (high CVP) but delivers little to the left heart (low wedge).","These patients are preload dependent, so nitrates and diuretics can crash their pressure; give fluids."]],
  ["CA-034","MECHANISM","Cardiac drugs","New drug reduces outward K⁺ current in phase 3 — most similar to","Dofetilide",["Lidocaine","Verapamil","Propranolol"],["Blocking the phase 3 potassium current prolongs repolarisation, the class III effect.","Class III drugs (amiodarone, sotalol, dofetilide, ibutilide) lengthen the action potential and QT.","Their main risk is torsades de pointes."]],
  ["CA-035","ASSOCIATION","Ischemic heart disease","A year-old MI scar in the left ventricle — its collagen type predominates in","Tendon",["Hyaline cartilage","Basement membrane","Lymph node stroma"],["An old infarct heals into a dense fibrous scar.","Early granulation tissue contains type III collagen, which is replaced by type I collagen over weeks.","Type I collagen is the main collagen of bone, skin, tendon and mature scar."]],
  ["CA-036","MECHANISM","Cardiomyopathy & tumors","Weeks of worsening dyspnea, then sudden death; autopsy heart has a huge dilated left ventricle","Weaker ventricular contraction",["Stiff, poorly filling ventricle","Outflow tract obstruction","Restricted pericardial filling"],["A dilated, thin-walled left ventricle is eccentric hypertrophy, as in dilated cardiomyopathy.","Its symptoms come from systolic dysfunction — a weak contraction and low ejection fraction.","Causes include genetic mutations, alcohol, myocarditis, doxorubicin and peripartum cardiomyopathy."]],
  ["CA-037","MECHANISM","Arrhythmias","Young man faints suddenly without warning; ECG shows only a long QT — inherited defect in","Membrane potassium channels",["Sarcomere myosin proteins","Desmosome junction proteins","Ryanodine receptor proteins"],["Congenital long QT syndrome most often comes from mutations in potassium channel genes.","Slower repolarisation lengthens the QT and allows early afterdepolarisations and torsades de pointes.","Romano-Ward is autosomal dominant; Jervell and Lange-Nielsen adds sensorineural deafness."]],
  ["CA-038","SIDE_EFFECT","Ischemic heart disease","Hours after fibrinolysis for MI: coma, unequal pupils, irregular breathing","Intracerebral hemorrhage",["Embolic stroke","Post-MI pericarditis","Ventricular free wall rupture"],["Fibrinolytics such as alteplase dissolve clots throughout the body, so bleeding is the main risk.","A sudden fall in consciousness after fibrinolysis is intracranial hemorrhage until proven otherwise.","Unequal pupils and irregular breathing signal raised intracranial pressure and impending herniation."]],
  ["CA-039","MECHANISM","Cardiac physiology","Healthy volunteer given IV nitroglycerin — change in cardiac and vascular function curves","Vascular curve shifts down and left",["Cardiac curve shifts up and left","Vascular curve rotates clockwise","Both curves shift up and right"],["Nitroglycerin is mainly a venodilator, increasing venous capacitance.","More blood pooled in the veins lowers mean systemic filling pressure, shifting the vascular function curve left.","Contractility is unchanged, so the cardiac function curve stays put; the operating point moves to lower preload."]],
  ["CA-040","MECHANISM","Cardiac drugs","Drug A flattens the maximal norepinephrine response without shifting the curve sideways","Phenoxybenzamine",["Phentolamine","Prazosin","Propranolol"],["A lower maximal response with no shift in potency means noncompetitive (irreversible) antagonism.","Phenoxybenzamine binds α receptors covalently, so extra norepinephrine cannot overcome it.","Phentolamine is a reversible competitive blocker that shifts the curve right instead."]],
  ["CA-041","MECHANISM","Hypertension","Started on valsartan and HCTZ; three weeks later BP and plasma renin activity are both unchanged","Not taking the medicine",["Primary aldosteronism","Renal artery stenosis","Drug-induced hyperkalemia"],["ARBs block angiotensin II feedback, and thiazides cause volume loss, so both should raise renin.","Renin that stays the same with no fall in blood pressure suggests the drugs are not being taken.","Nonadherence is the commonest reason for apparently resistant hypertension."]],
  ["CA-042","SIDE_EFFECT","Cardiac drugs","After a stent he starts a new drug and develops muscle aches with high CK — the drug also","Raises hepatic LDL receptor recycling",["Blocks intestinal cholesterol uptake","Inhibits lipoprotein lipase","Lowers hepatic VLDL secretion"],["Statins inhibit HMG-CoA reductase, the rate-limiting enzyme of cholesterol synthesis.","Lower cholesterol inside liver cells upregulates LDL receptors, which clear LDL from the blood.","Myopathy with raised CK and hepatotoxicity are the key adverse effects."]],
  ["CA-043","ASSOCIATION","Congenital & fetal","Short girl with hypertension and femoral pulses weaker than brachial — also likely has","Gonadal dysgenesis",["Lens subluxation","Polycystic kidneys","Hearing loss"],["Upper-limb hypertension with weak femoral pulses is coarctation of the aorta.","Coarctation and bicuspid aortic valve are the classic heart defects in Turner syndrome (45,X).","Turner syndrome causes short stature and gonadal dysgenesis with streak ovaries."]],
  ["CA-044","MECHANISM","Vascular disease","Tearing chest pain to the back with unequal arm pressures and normal troponin — initiating event","Intimal tear",["Medial calcification","Vasa vasorum rupture","Plaque rupture"],["Sudden tearing pain into the back with a blood pressure difference between arms is aortic dissection.","It begins with a tear in the intima, letting blood track along the media.","Hypertension is the biggest risk factor; cystic medial degeneration (Marfan) predisposes in the young."]],
  ["CA-045","DEFICIENCY","Heart failure & shock","Elderly man neglecting himself: high-output heart failure plus symmetric distal neuropathy","Thiamine",["Niacin","Cobalamin","Selenium"],["Wet beriberi is thiamine deficiency causing high-output heart failure from peripheral vasodilation.","Dry beriberi is a symmetric peripheral neuropathy, and both can occur together.","Thiamine is a cofactor for pyruvate dehydrogenase and α-ketoglutarate dehydrogenase."]],
  ["CA-046","ASSOCIATION","Cardiac physiology","Distance runner: slow pulse, borderline thick walls, bigger LV mass, normal EF — explanation","Cardiac adaptation",["Hypertrophic cardiomyopathy","Dilated cardiomyopathy","Restrictive cardiomyopathy"],["Athlete's heart is a normal adaptation to endurance training.","It shows a larger cavity, uniformly mildly thick walls and preserved function.","Unlike hypertrophic cardiomyopathy, it has normal diastolic filling and regresses with detraining."]],
  ["CA-047","ASSOCIATION","Congenital & fetal","Short teen girl with a webbed neck, broad chest, short 4th metacarpals and a murmur — echo likely shows","Bicuspid aortic valve",["Ventricular septal defect","Mitral valve prolapse","Transposition of great arteries"],["Short stature, broad chest and short fourth metacarpals point to Turner syndrome.","A bicuspid aortic valve is the commonest heart defect in Turner syndrome, followed by coarctation.","Bicuspid valves calcify early and cause aortic stenosis in middle age."]],
  ["CA-048","MECHANISM","Cardiac physiology","During a stress test, which value is nearly equal in the pulmonary and systemic circulations?","Blood flow per minute",["Mean arterial pressure","Vascular resistance","Total blood volume"],["The two circulations are in series, so the right and left ventricles must pump the same volume per minute.","The pulmonary circulation runs at much lower pressure because its resistance is much lower.","Any lasting mismatch in output would shift blood into one circuit within minutes."]],
  ["CA-049","ASSOCIATION","Ischemic heart disease","Persistent chest pain with ST elevation in I, aVL, V1–V4 and new Q waves — catheterisation shows","Ruptured plaque, fully blocking thrombus",["Stable plaque, partial thrombus","Coronary vasospasm, no plaque","Coronary dissection, no plaque"],["ST elevation with evolving Q waves is a transmural STEMI.","A STEMI comes from rupture of an atherosclerotic plaque with a thrombus that completely occludes the artery.","NSTEMI and unstable angina usually involve a partially occlusive thrombus."]],
  ["CA-050","ASSOCIATION","Congenital & fetal","Fetal blood samples range from 71% to 43% saturation — highest comes from","Inferior vena cava",["Superior vena cava","Ductus arteriosus","Pulmonary artery"],["Oxygenated blood from the placenta returns in the umbilical vein.","Most of it bypasses the liver through the ductus venosus into the inferior vena cava.","IVC blood is then streamed through the foramen ovale to the left heart and on to the brain."]],
  ["CA-051","ASSOCIATION","Pericardium","Past breast cancer, new axillary nodes and a large pericardial effusion — pericardiocentesis shows","Bloody fluid with atypical cells",["Clear fluid with lymphocytes","Milky fluid with chylomicrons","Purulent fluid with neutrophils"],["Malignancy is a common cause of a large pericardial effusion.","Lung and breast cancer and lymphoma are the usual primaries.","Malignant effusions are typically haemorrhagic and contain atypical cells on cytology."]],
  ["CA-052","MECHANISM","Cardiac drugs","Stable angina relieved by a drug converted to S-nitrosothiols in smooth muscle — main site of action","Large veins",["Large arteries","Coronary arterioles","Pulmonary capillaries"],["Nitrates release nitric oxide, which raises cGMP and relaxes vascular smooth muscle.","At usual doses they dilate large veins most, lowering preload and wall stress.","Lower preload reduces myocardial oxygen demand, which relieves the angina."]],
  ["CA-053","ASSOCIATION","Ischemic heart disease","Chest heaviness walking uphill, relieved by rest — pathology","Plaque narrowing lumen ≥70%, no thrombus",["Plaque rupture with occlusive thrombus","Plaque erosion with partial thrombus","Coronary vasospasm with normal lumen"],["Predictable exertional angina relieved by rest is stable angina.","It comes from a fixed atherosclerotic plaque that narrows the lumen by about 70% or more.","At rest flow is adequate, but demand during exertion outstrips supply."]],
  ["CA-054","ASSOCIATION","Vascular disease","Tearing back pain; TEE shows a flap only in the descending aorta — where does it begin?","Near the left subclavian artery",["At the aortic root","At the brachiocephalic trunk","At the renal arteries"],["A dissection confined to the descending aorta is Stanford type B.","Type B dissections usually start just distal to the origin of the left subclavian artery.","They are usually managed medically with blood pressure and heart rate control; type A needs surgery."]],
  ["CA-055","ASSOCIATION","Cardiac physiology","Infant with days of vomiting and diarrhea, tachycardic with poor turgor — lab pattern","Hematocrit, albumin and uric acid all up",["Hematocrit up, albumin and uric acid down","Hematocrit, albumin and uric acid all down","Hematocrit and albumin down, uric acid up"],["Losing salt and water shrinks plasma volume and concentrates the cells and proteins left behind.","Hematocrit and albumin rise because they are no longer diluted.","Uric acid rises because the proximal tubule reabsorbs more of it when volume is low."]],
  ["CA-056","MECHANISM","Cardiac drugs","Drug for AF widens the QRS with little QT change — which action potential phase?","Phase 0",["Phase 2","Phase 3","Phase 4"],["Widening the QRS without lengthening QT is the class IC pattern (flecainide, propafenone).","Class IC drugs strongly block fast sodium channels, slowing phase 0 depolarisation.","They barely change the action potential duration, so the QT stays nearly the same."]],
  ["CA-057","MECHANISM","Ischemic heart disease","Young agitated man with chest pain, dilated pupils, tachycardia, hypertension — cause of the pain","Coronary vasoconstriction",["Coronary plaque rupture","Aortic dissection","Pericardial inflammation"],["Cocaine blocks reuptake of norepinephrine, causing sympathetic overdrive.","α-mediated coronary vasospasm and increased demand cause ischemia.","Treat with benzodiazepines and nitrates; avoid pure β-blockers, which leave α vasoconstriction unopposed."]],
  ["CA-058","SIDE_EFFECT","Hypertension","Elderly woman with fainting and a pulse of 44 that stops when a BP drug is withdrawn — its mechanism","Less presynaptic norepinephrine release",["Blocked postsynaptic α1 receptors","Blocked cardiac L-type calcium channels","Blocked angiotensin II receptors"],["Clonidine stimulates central α2 receptors, which reduce sympathetic outflow and norepinephrine release.","The result is lower heart rate and vascular resistance, which can cause bradycardia and syncope.","Stopping clonidine suddenly can cause rebound hypertension."]],
  ["CA-059","MECHANISM","Cardiac drugs","New sodium blocker unbinds from channels much faster than quinidine — most like","Lidocaine",["Flecainide","Procainamide","Disopyramide"],["Class IB drugs bind and release sodium channels quickly.","They act most on rapidly firing or depolarised tissue, such as ischemic ventricle.","Lidocaine and mexiletine are used for ventricular arrhythmias after MI."]],
  ["CA-060","ASSOCIATION","Valves & endocarditis","Recent endocarditis; phonocardiogram shows a holosystolic murmur at the LLSB louder on inspiration","Tricuspid regurgitation",["Mitral regurgitation","Ventricular septal defect","Pulmonic stenosis"],["A holosystolic murmur at the left lower sternal border is tricuspid regurgitation or a VSD.","Right-sided murmurs get louder on inspiration (Carvallo sign) because venous return rises.","Endocarditis in injection drug use often damages the tricuspid valve."]],
  ["CA-061","ASSOCIATION","Anatomy","Femoral angiogram: the arrow marks a branch off the external iliac just above the inguinal ligament","Inferior epigastric",["Deep circumflex iliac","Superficial epigastric","Obturator"],["The inferior epigastric artery arises from the external iliac just above the inguinal ligament.","It runs up the posterior rectus sheath and marks the lateral edge of Hesselbach triangle.","A high femoral puncture can injure it and cause retroperitoneal bleeding."]],
  ["CA-062","ASSOCIATION","Heart failure & shock","Autopsy lung full of macrophages packed with brown pigment — most likely cause","Reduced LV systolic function",["Coal dust inhalation","Smoking-related emphysema","Iron overload syndrome"],["Hemosiderin-laden macrophages are called heart failure cells.","Left heart failure causes chronic pulmonary congestion, and red cells leak into alveoli.","Alveolar macrophages break down the hemoglobin, leaving brown hemosiderin."]],
  ["CA-063","ASSOCIATION","Cardiomyopathy & tumors","Athlete's systolic murmur at the LSB softens with handgrip and leg raise — echo shows","Thick wall, small cavity, impaired relaxation",["Thin wall, large cavity, low ejection","Normal wall, prolapsing mitral leaflet","Thick wall, large cavity, low ejection"],["A murmur that softens with maneuvers that increase preload or afterload is hypertrophic cardiomyopathy.","More blood in the ventricle pushes the septum and mitral leaflet apart, reducing outflow obstruction.","Echo shows asymmetric septal hypertrophy, a small cavity, preserved EF and diastolic dysfunction."]],
  ["CA-064","MECHANISM","Vascular disease","Older male smoker with a pulsatile midline abdominal mass — process behind it","Chronic transmural inflammation",["Cystic medial degeneration","Intimal tear and dissection","Fibromuscular dysplasia"],["A pulsatile abdominal mass in an older male smoker is an abdominal aortic aneurysm.","Inflammation across the wall releases matrix metalloproteinases that break down elastin and collagen.","Smoking is the strongest risk factor, and men over 65 who have smoked are screened by ultrasound."]],
  ["CA-065","ASSOCIATION","Cardiomyopathy & tumors","Young man dies playing basketball; heart shows asymmetric septal hypertrophy — premortem finding","Fourth heart sound",["Opening snap","Pericardial friction rub","Third heart sound"],["Asymmetric septal hypertrophy is hypertrophic cardiomyopathy.","The thick, stiff ventricle depends on the atrial kick, producing an S4.","Exertional dyspnea and syncope warn of outflow obstruction and arrhythmia."]],
  ["CA-066","MECHANISM","Cardiac drugs","Cortisol alone does not constrict vessels, but it greatly enhances norepinephrine's effect","Permissiveness",["Synergism","Potentiation","Tachyphylaxis"],["A permissive hormone has little effect alone but allows another hormone to work fully.","Cortisol upregulates α1 receptors, so vessels respond better to catecholamines.","This is why adrenal insufficiency can cause hypotension that resists pressors."]],
  ["CA-067","ASSOCIATION","Vascular disease","Sweet-pea fed rabbits show proteoglycan pooling in the aortic media with intact intima — resembles","Aortic aneurysm",["Atherosclerotic plaque","Takayasu arteritis","Mönckeberg sclerosis"],["Sweet peas contain lathyrogens that block lysyl oxidase and weaken collagen and elastin cross-links.","The result is cystic medial degeneration — pools of proteoglycan in the media.","Cystic medial degeneration weakens the wall and predisposes to aneurysm and dissection, as in Marfan syndrome."]],
  ["CA-068","ASSOCIATION","Anatomy","Septic patient needs femoral venous access; the femoral pulse is felt — where to insert?","Just medial to the artery",["Just lateral to the artery","Directly over the artery","Above the inguinal ligament"],["In the femoral triangle the order from lateral to medial is nerve, artery, vein, then lymphatics (NAVeL).","The femoral vein lies just medial to the arterial pulse.","Puncture below the inguinal ligament avoids retroperitoneal bleeding."]],
  ["CA-069","ASSOCIATION","Heart failure & shock","Pyelonephritis with BP 70/40 and flat neck veins — early hemodynamic pattern","Low PCWP, high CI, low SVR, high SvO₂",["High PCWP, low CI, high SVR, low SvO₂","Low PCWP, low CI, high SVR, low SvO₂","Low PCWP, high CI, high SVR, high SvO₂"],["Early septic shock is a warm distributive shock.","Vasodilation lowers SVR and filling pressures, while cardiac output rises to compensate.","Mixed venous oxygen is high because tissue oxygen extraction is impaired."]],
  ["CA-070","ASSOCIATION","Cardiomyopathy & tumors","Elderly man with HFpEF; LV diastolic pressure–volume curve shifted up and left","Transthyretin deposition",["Iron overload of the heart","Alcohol-induced myocyte loss","Viral myocarditis"],["A curve shifted up and left means a stiff ventricle — higher pressure at every volume.","In an elderly man, wild-type transthyretin amyloid deposits stiffen the myocardium.","It causes restrictive cardiomyopathy with heart failure with preserved ejection fraction."]],
  ["CA-071","MECHANISM","Congenital & fetal","Preterm infant with a large PDA has it clipped — immediate change","Higher LV afterload",["Lower LV afterload","Higher pulmonary blood flow","Lower aortic diastolic pressure"],["A patent ductus lets blood run off from the aorta to the pulmonary artery during diastole.","Closing it ends the run-off, so aortic diastolic pressure and left ventricular afterload rise.","Pulmonary blood flow falls, relieving pulmonary edema."]],
  ["CA-072","SIDE_EFFECT","Cardiac drugs","Man with heart rhythm problems develops arthralgia, malar rash and a high ANA — ask about","Procainamide",["Amiodarone","Digoxin","Metoprolol"],["Drug-induced lupus causes arthralgia, fever, rash and serositis with anti-histone antibodies.","Procainamide and hydralazine are the classic causes, especially in slow acetylators.","Kidney and CNS involvement are rare, and it resolves when the drug is stopped."]],
  ["CA-073","MECHANISM","Cardiac physiology","Holter shows a premature ventricular beat (Y) between normal beats X and Z — rank LV end-diastolic volumes","Z > X > Y",["X > Y > Z","Y > X > Z","X = Z > Y"],["A premature beat arrives early, so the ventricle has less time to fill.","The compensatory pause after the premature beat gives extra filling time before the next beat.","So the beat after the pause has the largest end-diastolic volume and the strongest contraction (Frank-Starling)."]],
  ["CA-074","MECHANISM","Heart failure & shock","Worsening dyspnea, orthopnea, raised JVP and leg edema — neurohormonal driver of the worsening","Increased sympathetic activity",["Increased natriuretic peptides","Reduced renin release","Reduced vasopressin release"],["In heart failure, low effective circulating volume activates the sympathetic system and RAAS.","These raise heart rate, afterload and sodium and water retention, which worsens congestion.","β-blockers, ACE inhibitors, ARBs and mineralocorticoid antagonists block these pathways."]],
  ["CA-075","SIDE_EFFECT","Hypertension","Treated hypertensive with mildly high calcium, low PTH and normal kidneys — cause","Medication effect",["Primary hyperparathyroidism","Sarcoidosis","Hidden malignancy"],["Thiazides increase calcium reabsorption in the distal convoluted tubule.","Raised calcium suppresses parathyroid hormone.","Thiazide side effects are hyperglycemia, hyperlipidemia, hyperuricemia, hypercalcemia and hypokalemia."]],
  ["CA-076","ASSOCIATION","Ischemic heart disease","Autopsy myocardium: dense neutrophil infiltrate at the edge of necrotic muscle — age of the infarct","1 to 3 days",["Under 4 hours","3 to 14 days","Over 2 months"],["Within 4 hours there are few visible changes; coagulative necrosis appears at 4 to 24 hours.","Neutrophils flood in at 1 to 3 days, which is when fibrinous pericarditis can appear.","Macrophages dominate at 3 to 14 days, followed by granulation tissue and then scar."]],
  ["CA-077","MECHANISM","Cardiac physiology","Pacemaker cell action potential: ion behind the upstroke marked by the arrow","Calcium",["Sodium","Potassium","Chloride"],["Sinoatrial and AV nodal cells have no fast sodium current for their upstroke.","Their phase 0 is driven by calcium entering through L-type channels, so it is slow.","Phase 4 is the funny current (If), a slow sodium inflow that sets the heart rate."]],
  ["CA-078","ASSOCIATION","Vascular disease","Cashier with heavy legs and dilated, twisting calf veins — risk of which complication?","Skin ulceration",["Pulmonary embolism","Arterial claudication","Leg lymphedema"],["Varicose veins come from incompetent venous valves, worsened by long periods of standing.","Chronic venous hypertension leads to edema, stasis dermatitis and skin breakdown.","Venous ulcers form near the medial malleolus; superficial varicosities rarely cause pulmonary embolism."]],
  ["CA-079","MECHANISM","Cardiac drugs","After drug A, low-dose epinephrine no longer raises heart rate and now raises diastolic pressure","Propranolol",["Prazosin","Metoprolol","Phentolamine"],["Low-dose epinephrine normally acts on β1 (raising heart rate) and β2 (dilating muscle vessels, lowering diastolic pressure).","With all β receptors blocked, only the α1 vasoconstriction is left, so diastolic pressure rises.","Losing both β1 and β2 effects means a nonselective blocker such as propranolol."]],
  ["CA-080","ASSOCIATION","Ischemic heart disease","Sharp left parasternal pain after moving furniture, reproduced by pressing the chest wall","Costochondritis",["Unstable angina","Acute pericarditis","Pulmonary embolism"],["Pain that is reproduced by palpation and worsened by movement points to the chest wall.","Costochondritis is inflammation of the costosternal joints, often after strain.","It is benign and treated with rest and NSAIDs once cardiac causes are excluded."]],
  ["CA-081","ASSOCIATION","Pericardium","Advanced CKD, distant heart sounds and pulsus paradoxus — echo finding","Engorged inferior vena cava",["Thickened calcified pericardium","Dilated, weak left ventricle","Thickened mitral leaflets"],["Uremia can cause pericarditis with a large effusion and tamponade.","Tamponade raises right atrial pressure, so the IVC is dilated and barely collapses with breathing.","Echo also shows diastolic collapse of the right atrium and right ventricle."]],
  ["CA-082","MECHANISM","Hypertension","GFR dips modestly in the first week of enalapril — which vessel explains it?","Efferent arterioles",["Afferent arterioles","Peritubular capillaries","Renal arcuate arteries"],["Angiotensin II preferentially constricts the efferent arteriole, maintaining glomerular pressure.","ACE inhibitors lower angiotensin II, so the efferent arteriole relaxes and GFR falls slightly.","A rise in creatinine of up to about 30% is expected; a bigger rise suggests bilateral renal artery stenosis."]],
  ["CA-083","ASSOCIATION","Valves & endocarditis","Murmur best heard leaning forward; catheter tracing of AR — when is it loudest?","Early diastole, right after aortic closure",["Late diastole, before mitral closure","Midsystole, at peak ejection","Late systole, before aortic closure"],["Aortic regurgitation causes a high-pitched, blowing, decrescendo diastolic murmur.","The pressure gap between aorta and ventricle is greatest right after the aortic valve closes, so the murmur is loudest then.","It is heard best at the left sternal border with the patient sitting up and leaning forward."]],
  ["CA-084","ASSOCIATION","Vascular disease","Dizziness while playing table tennis; left vertebral artery flow is reversed — which artery is blocked?","Left subclavian",["Left common carotid","Basilar artery","Left internal carotid"],["A stenosis of the subclavian artery before the vertebral artery origin causes subclavian steal.","When the arm works hard, blood is pulled backward down the vertebral artery to supply it.","This steals blood from the brainstem, causing dizziness and a lower blood pressure in that arm."]],
  ["CA-085","ASSOCIATION","Cardiomyopathy & tumors","Young man dies in sleep; mother had a heart transplant at 40; TTN (titin) mutation — phenotype","Dilated cardiomyopathy",["Hypertrophic cardiomyopathy","Restrictive cardiomyopathy","Arrhythmogenic cardiomyopathy"],["Truncating TTN mutations are the commonest genetic cause of familial dilated cardiomyopathy.","Titin is a giant sarcomere protein that gives myocytes their elasticity.","Familial dilated cardiomyopathy is usually autosomal dominant and causes heart failure and arrhythmias."]],
  ["CA-086","ASSOCIATION","Congenital & fetal","Boy with cyanotic spells relieved by squatting and a harsh systolic murmur — embryologic cause","Infundibular septum deviates forward",["Endocardial cushions fail to fuse","Aorticopulmonary septum fails to spiral","Septum primum fails to form"],["Squatting during blue spells is classic tetralogy of Fallot.","Anterosuperior deviation of the infundibular septum causes pulmonary stenosis, a VSD, an overriding aorta and RV hypertrophy.","Squatting raises systemic vascular resistance, which pushes more blood into the lungs."]],
  ["CA-087","ASSOCIATION","Anatomy","Rheumatic heart disease; dysphagia from extrinsic compression of the mid esophagus — enlarged structure","Left atrium",["Right atrium","Aortic arch","Left ventricle"],["The left atrium is the most posterior chamber and sits directly in front of the esophagus.","Mitral stenosis or regurgitation enlarges the left atrium, which can compress the esophagus.","A big left atrium can also compress the left recurrent laryngeal nerve, causing hoarseness (Ortner syndrome)."]],
  ["CA-088","MECHANISM","Arrhythmias","Lethargic infant with a narrow-complex regular rhythm of 240 and no P waves — why is BP low?","Shortened ventricular diastole",["Lost atrial contraction","Weaker ventricular contraction","Lower vascular resistance"],["A regular narrow-complex tachycardia this fast with no P waves is supraventricular tachycardia.","As heart rate rises, diastole shortens much more than systole.","Less filling time reduces stroke volume and cardiac output, so blood pressure falls."]],
  ["CA-089","SIDE_EFFECT","Cardiac drugs","Dofetilide is started for paroxysmal AF — main risk","Polymorphic ventricular tachycardia",["Pulmonary fibrosis","Drug-induced lupus","High-grade AV block"],["Dofetilide is a pure class III drug that blocks the rapid delayed rectifier K⁺ current.","Blocking repolarisation lengthens the QT and can trigger torsades de pointes.","It is started in hospital with QT monitoring and dosed by renal function."]],
  ["CA-090","ASSOCIATION","Congenital & fetal","Wide, fixed S2 split and an enlarged right heart border — repair aims to protect which structure?","Pulmonary vessels",["Aortic valve","Mitral valve","Coronary arteries"],["Wide, fixed splitting of S2 is an atrial septal defect.","Years of extra left-to-right flow remodel the pulmonary arteries and raise pulmonary resistance.","Once pressures reverse the shunt (Eisenmenger syndrome) the change is irreversible, so ASDs are closed early."]],
  ["CA-091","MECHANISM","Cardiac physiology","Conduction velocities 0.05, 0.3, 1.1 and 2.2 m/s — match the tissues","AV node, ventricle, atrium, Purkinje",["AV node, atrium, ventricle, Purkinje","Purkinje, atrium, ventricle, AV node","Atrium, AV node, Purkinje, ventricle"],["The AV node is slowest, which gives the ventricles time to fill.","Purkinje fibres are fastest, so the ventricles contract together.","Speed order: Purkinje > atria > ventricles > AV node (\"Park At Venture AVenue\")."]],
  ["CA-092","ASSOCIATION","Congenital & fetal","Healthy boy: harsh holosystolic murmur at the LLSB that gets louder with handgrip","Ventricular septal defect",["Hypertrophic cardiomyopathy","Atrial septal defect","Pulmonic stenosis"],["A ventricular septal defect is the commonest congenital heart defect.","A small VSD gives a loud, harsh holosystolic murmur at the left lower sternal border.","Handgrip raises afterload, pushing more blood across the defect and making the murmur louder."]],
  ["CA-093","MECHANISM","Cardiac drugs","Phenylephrine infusion in septic shock; heart rate then falls — expected intracellular changes","Myocyte cAMP ↓, smooth muscle IP₃ ↑, nodal Ca²⁺ ↓",["Myocyte cAMP ↑, smooth muscle IP₃ ↑, nodal Ca²⁺ ↑","Myocyte cAMP ↓, smooth muscle IP₃ ↓, nodal Ca²⁺ ↓","Myocyte cAMP ↑, smooth muscle IP₃ ↓, nodal Ca²⁺ ↑"],["Phenylephrine stimulates α1 receptors, which act through Gq to raise IP₃ in vascular smooth muscle.","The rise in pressure triggers a baroreflex that withdraws sympathetic tone and boosts vagal tone.","Less β1 stimulation lowers cAMP in myocytes and the calcium current in nodal cells, slowing the heart."]],
  ["CA-094","SIDE_EFFECT","Cardiac drugs","AF patient on a new drug has sinus bradycardia, QTc 508 and a run of torsades — which drug?","Sotalol",["Metoprolol","Diltiazem","Flecainide"],["Sotalol combines β-blockade (class II) with potassium channel blockade (class III).","β-blockade slows the heart, and slower rates lengthen the QT further.","This combination makes torsades de pointes the key risk, so sotalol is started with QT monitoring."]],
  ["CA-095","ASSOCIATION","Cardiac physiology","Jugular venous tracing: the first and tallest wave — which event?","Atrial contraction",["Tricuspid valve bulging","Venous filling of atrium","Rapid ventricular filling"],["The a wave is right atrial contraction at the end of diastole.","It is absent in atrial fibrillation and huge (cannon a waves) when the atrium contracts against a closed tricuspid valve.","The c wave is tricuspid bulging, the v wave is atrial filling, and the y descent is early ventricular filling."]],
  ["CA-096","ASSOCIATION","Pericardium","Man from Russia with right heart failure, steep y descent and a calcified pericardium on CT","Constrictive pericarditis",["Restrictive cardiomyopathy","Cardiac tamponade","Pulmonary hypertension"],["A thick, rigid pericardium stops the heart filling once it reaches its limit, giving a sharp y descent.","Tuberculosis is a leading cause worldwide; radiation and cardiac surgery are others.","Signs include Kussmaul sign, a pericardial knock and right-sided congestion."]],
  ["CA-097","ASSOCIATION","Valves & endocarditis","Sudden death on exertion; autopsy shows thick LV walls with a small cavity and no scar — cause","Aortic stenosis",["Aortic regurgitation","Mitral regurgitation","Dilated cardiomyopathy"],["Thick walls with a small cavity are concentric hypertrophy, the response to pressure overload.","Severe aortic stenosis causes angina, syncope and heart failure on exertion.","Sudden death can occur, especially with exertion, as the fixed outflow cannot meet demand."]],
  ["CA-098","ASSOCIATION","Anatomy","TEE probe in the mid esophagus facing forward — closest chamber","Left atrium",["Right ventricle","Left ventricle","Right atrium"],["The left atrium forms most of the posterior surface of the heart.","It lies directly in front of the esophagus, which is why TEE images it so well.","TEE is the best test for left atrial appendage clots and valve vegetations."]],
  ["CA-099","ASSOCIATION","Anatomy","TEE probe in the mid esophagus turned backward — structure seen best","Descending aorta",["Azygos vein","Thoracic duct","Left main bronchus"],["At heart level, the descending thoracic aorta lies behind and slightly left of the esophagus.","Turning the TEE probe backward brings the descending aorta into view.","TEE is used to look for aortic dissection when CT is not possible."]],
  ["CA-100","ASSOCIATION","Cardiac physiology","Elderly heart: smaller LV cavity, sigmoid septum, more collagen and brown perinuclear granules","Normal ageing",["Hypertrophic cardiomyopathy","Cardiac hemochromatosis","Healed myocarditis"],["The ageing heart develops a smaller left ventricular cavity and a sigmoid-shaped septum.","Interstitial collagen increases, which stiffens the ventricle.","Brown perinuclear lipofuscin granules are wear-and-tear pigment from lipid peroxidation."]],
  ["CA-101","ASSOCIATION","Congenital & fetal","Infant with defects in the lower atrial septum and the ventricular septum — associated with","Autosomal trisomy",["Sex chromosome monosomy","22q11 microdeletion","Fibrillin-1 mutation"],["Defects of both septa where they meet the valves are a complete atrioventricular canal defect.","It comes from failure of the endocardial cushions to fuse.","AV canal defects are the commonest heart lesion in Down syndrome (trisomy 21)."]],
  ["CA-102","MECHANISM","Cardiac physiology","Clamp mimics a 60% coronary stenosis — steady state beyond it","Lower pressure, unchanged flow",["Lower pressure, lower flow","Higher pressure, unchanged flow","Unchanged pressure, lower flow"],["A significant stenosis drops the pressure downstream.","Coronary autoregulation dilates the downstream arterioles to keep flow normal at rest.","This reserve is used up in severe stenosis, so ischemia appears with exertion first."]],
  ["CA-103","ASSOCIATION","Cardiac physiology","During surgery the PV loop's end-diastolic corner shifts right, rest unchanged — cause","Normal saline infusion",["Epinephrine infusion","Phenylephrine infusion","Hemorrhage"],["Moving the end-diastolic point to the right means a larger end-diastolic volume — higher preload.","IV fluids raise venous return and preload.","More preload widens the loop and increases stroke volume by the Frank-Starling mechanism."]],
  ["CA-104","ASSOCIATION","Anatomy","IVC filter for a DVT in a patient who cannot be anticoagulated — on CT at L2 it lies","In front of the right side of the vertebra",["In front of the left side of the vertebra","Behind the right crus of the diaphragm","Between the aorta and the SMA"],["Filters go in the infrarenal inferior vena cava when anticoagulation is not possible.","The IVC runs to the right of the aorta, in front of the right half of the vertebral bodies.","The left renal vein crosses between the aorta and SMA to reach the IVC."]],
  ["CA-105","MECHANISM","Hypertension","Switched from lisinopril (cough) to losartan — effect on the RAAS and bradykinin","Renin, Ang I and Ang II up, aldosterone down",["Renin up, Ang II down, aldosterone down","Renin down, Ang II up, aldosterone up","Renin, Ang I and Ang II down, aldosterone up"],["Losartan blocks the AT1 receptor, so angiotensin II cannot act.","Loss of feedback raises renin, angiotensin I and angiotensin II, while aldosterone falls.","ACE still breaks down bradykinin, so bradykinin and the cough are unchanged from normal."]],
  ["CA-106","ASSOCIATION","Heart failure & shock","Anterior STEMI with hypotension, crackles and an S3 — hemodynamics","Wedge high, CVP high, coronary perfusion low",["Wedge low, CVP high, coronary perfusion low","Wedge high, CVP low, coronary perfusion high","Wedge low, CVP low, coronary perfusion high"],["A large anterior infarct can cause cardiogenic shock from left ventricular failure.","Blood backs up into the lungs and then the right heart, raising wedge pressure and CVP.","Low aortic pressure and high LV diastolic pressure reduce coronary perfusion pressure, worsening ischemia."]],
  ["CA-107","ASSOCIATION","Cardiomyopathy & tumors","Man faints; sinus node dysfunction, diastolic dysfunction, enlarged liver and bronze skin — cause","Iron accumulation",["Amyloid deposition","Granuloma formation","Glycogen storage"],["Hereditary hemochromatosis deposits iron in the heart, liver, pancreas and skin.","Cardiac iron causes restrictive physiology early and dilated cardiomyopathy later, plus conduction disease.","It is usually an HFE C282Y mutation and is treated with phlebotomy."]],
  ["CA-108","ASSOCIATION","Cardiomyopathy & tumors","82-year-old with HFpEF, thick walls, normal EF; biopsy shows amorphous pink material between myocytes","Senile amyloidosis",["Hypertrophic cardiomyopathy","Cardiac sarcoidosis","Hypertensive heart disease"],["Wild-type transthyretin deposits in the heart with age (senile systemic amyloidosis).","The amyloid stiffens the ventricle, causing restrictive cardiomyopathy and diastolic heart failure.","It stains with Congo red and shows apple-green birefringence under polarised light."]],
  ["CA-109","MECHANISM","Hypertension","Diabetic with albuminuria who coughed on lisinopril — best antihypertensive","Valsartan",["Amlodipine","Hydrochlorothiazide","Metoprolol"],["ACE inhibitors cause cough because bradykinin builds up.","ARBs block the AT1 receptor directly, so they give the same kidney protection without the cough.","In diabetes with albuminuria, ACE inhibitors or ARBs slow progression of nephropathy."]],
  ["CA-110","ASSOCIATION","Arrhythmias","Active 72-year-old with palpitations; ECG shows atrial fibrillation — strongest risk factor","Advanced age",["Endurance exercise","Caffeine intake","Male sex"],["Atrial fibrillation becomes far more common with each decade of life.","Ageing causes atrial fibrosis and dilation, which create the substrate for fibrillation.","Hypertension, heart failure, valve disease, alcohol and hyperthyroidism also raise the risk."]],
  ["CA-111","ASSOCIATION","Heart failure & shock","Heart failure with EF 55% and a nondilated left ventricle — most associated factor","Increased afterload",["Increased contractility","Decreased preload","Decreased heart rate"],["Heart failure with preserved ejection fraction is mainly diastolic dysfunction.","Long-standing hypertension (increased afterload) causes concentric hypertrophy and a stiff ventricle.","Other risks include older age, female sex, obesity, diabetes and atrial fibrillation."]],
  ["CA-112","SIDE_EFFECT","Arrhythmias","Teen with a KCNH2 mutation faints at rest after starting a new medicine — which drug?","Erythromycin",["Amoxicillin","Doxycycline","Cephalexin"],["KCNH2 (hERG) encodes the rapid delayed rectifier potassium channel; loss of function causes congenital long QT.","Macrolides such as erythromycin also block this channel.","Adding a QT-prolonging drug to a long QT syndrome can trigger torsades de pointes."]],
  ["CA-113","ASSOCIATION","Valves & endocarditis","Pregnant woman with a 3/6 midsystolic murmur at the LUSB and a widely split S2","Pulmonic stenosis",["Atrial septal defect","Aortic stenosis","Mitral regurgitation"],["Pulmonic stenosis causes a crescendo-decrescendo murmur at the left upper sternal border.","The right ventricle takes longer to empty, delaying P2 and widening the split.","Pregnancy's extra blood volume can unmask a congenital lesion."]],
  ["CA-114","MECHANISM","Hypertension","3 L of saline stretches the heart and a peptide hormone rises — it increases","Glomerular filtration rate",["Renin secretion","Aldosterone secretion","Collecting duct water uptake"],["Atrial and ventricular stretch releases ANP and BNP.","Natriuretic peptides dilate the afferent and constrict the efferent arteriole, raising GFR.","They also block sodium reabsorption and inhibit renin and aldosterone, so sodium and water are excreted."]],
  ["CA-115","ASSOCIATION","Vascular disease","Months of constitutional symptoms, cavitating lung nodules and hematuria — lung histology","Necrotising vasculitis with granulomas",["Eosinophilic vasculitis with asthma","Immune complex vasculitis, no granulomas","Giant-cell vasculitis of the aorta"],["Upper airway, lung and kidney disease together suggest granulomatosis with polyangiitis.","Biopsy shows necrotising vasculitis with granulomatous inflammation.","It is associated with c-ANCA (anti-PR3) and treated with glucocorticoids plus rituximab or cyclophosphamide."]],
  ["CA-116","MECHANISM","Cardiac drugs","Sildenafil restores erections; its intracellular signal is most like that of","Brain natriuretic peptide",["Norepinephrine","Angiotensin II","Endothelin"],["Sildenafil inhibits phosphodiesterase 5, so cGMP builds up and smooth muscle relaxes.","BNP and ANP act through membrane guanylyl cyclase, also raising cGMP.","Nitric oxide raises cGMP through soluble guanylyl cyclase, which is why nitrates plus sildenafil can crash blood pressure."]],
  ["CA-117","SIDE_EFFECT","Cardiac drugs","Long-term amiodarone is planned after cardioversion — which baseline test?","Serum TSH",["Serum ferritin","Serum lipase","Serum potassium"],["Amiodarone is about one-third iodine by weight and resembles thyroid hormone.","It can cause both hypothyroidism and hyperthyroidism.","Baseline thyroid, liver and lung function tests are needed, with regular monitoring after."]],
  ["CA-118","ASSOCIATION","Valves & endocarditis","Young man with pounding palpitations and head bobbing with each heartbeat — expected finding","Wide pulse pressure",["Narrow pulse pressure","Pulsus paradoxus","Pulsus parvus et tardus"],["Head bobbing (de Musset sign) is a sign of chronic aortic regurgitation.","A large stroke volume raises systolic pressure, and regurgitant run-off lowers diastolic pressure.","Other signs include bounding (water-hammer) pulses and pulsating nail beds (Quincke sign)."]],
  ["CA-119","ASSOCIATION","Heart failure & shock","Fainting with shock: right atrial pressure 17, wedge 7 mm Hg — likely cause","Right ventricular infarction",["Left ventricular infarction","Septic shock","Hemorrhagic shock"],["A high right atrial pressure with a low wedge pressure means the right ventricle is failing to deliver blood.","Right ventricular infarction usually comes with an inferior MI from right coronary occlusion.","Treat with fluids and avoid nitrates, which drop the preload these patients depend on."]],
  ["CA-120","ASSOCIATION","Heart failure & shock","Refractory shock; autopsy shows hippocampal necrosis — also likely necrotic in the colon","Splenic flexure",["Sigmoid colon","Cecum","Ascending colon"],["Prolonged hypotension injures tissues with high oxygen demand, such as hippocampal neurons.","Watershed zones at the border of two arterial supplies are also vulnerable.","In the colon, the splenic flexure lies between the superior and inferior mesenteric territories."]],
  ["CA-121","MECHANISM","Cardiac drugs","Isosorbide dinitrate taken morning and afternoon but not evening — the gap prevents","Tolerance",["Headache","Hypotension","Reflex tachycardia"],["Continuous nitrate exposure quickly causes tolerance, as the vessels respond less.","A nitrate-free interval of 10 to 12 hours each day restores responsiveness.","The gap is usually overnight, when angina is least likely."]],
  ["CA-122","ASSOCIATION","Cardiac physiology","Hypertensive diabetic: low-pitched extra sound just before S1 at the apex","Left ventricular hypertrophy",["Left ventricular dilation","Mitral valve prolapse","Aortic regurgitation"],["A sound just before S1 is an S4, from the atrium contracting into a stiff ventricle.","Long-standing hypertension causes concentric hypertrophy and reduced compliance.","An S4 is heard best at the apex with the bell, patient lying on the left."]],
  ["CA-123","ASSOCIATION","Ischemic heart disease","Dies 30 minutes after chest pain; RCA plaque with occlusive clot — immediate cause of death","Ventricular fibrillation",["Free wall rupture","Cardiogenic shock","Complete heart block"],["Most sudden deaths in acute MI happen within the first hour.","Ischemic myocardium is electrically unstable and can degenerate into ventricular fibrillation.","Free wall rupture and papillary muscle rupture happen days later."]],
  ["CA-124","MECHANISM","Cardiac drugs","Digoxin improves his heart failure symptoms — the first cellular event","Less Na⁺ leaving myocytes",["More K⁺ entering myocytes","More Ca²⁺ leaving myocytes","Less Ca²⁺ entering myocytes"],["Digoxin inhibits the Na⁺/K⁺-ATPase, so sodium builds up inside the cell.","Higher intracellular sodium slows the Na⁺/Ca²⁺ exchanger, so calcium builds up too.","More calcium is stored and released, so contraction strengthens; digoxin also increases vagal tone."]],
  ["CA-125","MECHANISM","Cardiac drugs","HFrEF patient starts sacubitril–valsartan — main effect","More urinary sodium excretion",["Less urinary sodium excretion","More renin release","More bradykinin breakdown"],["Sacubitril inhibits neprilysin, the enzyme that breaks down natriuretic peptides.","Higher ANP and BNP cause natriuresis, diuresis and vasodilation.","Neprilysin also breaks down angiotensin II, so an ARB is added to block it; angioedema is a risk."]],
  ["CA-126","ASSOCIATION","Heart failure & shock","Decompensated heart failure with a displaced apex and 3+ edema — which value is increased?","Arteriolar resistance",["Venous capacitance","Stroke volume","Ejection fraction"],["Low cardiac output activates the sympathetic nervous system and the RAAS.","Both constrict arterioles, raising systemic vascular resistance and afterload.","Higher afterload further reduces output, a vicious cycle that vasodilators interrupt."]],
  ["CA-127","ASSOCIATION","Vascular disease","Older male smoker: sudden lower abdominal and back pain, fainting and hypotension","Ruptured aortic aneurysm",["Renal colic","Acute mesenteric ischemia","Acute pancreatitis"],["Pain, hypotension and a pulsatile mass form the classic triad of a ruptured AAA.","Rupture is usually into the left retroperitoneum, which can briefly contain the bleeding.","Risk rises with aneurysm size over 5.5 cm, rapid growth, smoking and female sex."]],
  ["CA-128","MECHANISM","Cardiac drugs","Obtunded with hypotension and bradycardia; IV glucagon helps — intracellular change","More cAMP in cardiac myocytes",["Less cAMP in cardiac myocytes","More cGMP in cardiac myocytes","Less Ca²⁺ in cardiac myocytes"],["This is likely a β-blocker overdose.","Glucagon has its own Gs-coupled receptor on myocytes that bypasses the blocked β receptors.","Raising cAMP increases heart rate and contractility, reversing the toxicity."]],
  ["CA-129","MECHANISM","Cardiac drugs","Arrhythmia drug that lengthens QT but rarely causes torsades","Amiodarone",["Sotalol","Dofetilide","Quinidine"],["Amiodarone blocks K⁺, Na⁺ and Ca²⁺ channels and β receptors (all four classes).","It prolongs the QT but makes repolarisation more uniform, so torsades is rare.","Its toxicities are pulmonary fibrosis, hepatotoxicity, thyroid disease, corneal deposits and blue-gray skin."]],
  ["CA-130","MECHANISM","Ischemic heart disease","Young woman woken by crushing chest pain; ST elevation but clean coronaries — mechanism","Hyperreactive vascular smooth muscle",["Plaque rupture with thrombus","Coronary artery dissection","Coronary embolism from the atrium"],["Chest pain at rest, often at night, with transient ST elevation and normal coronaries is vasospastic angina.","Coronary smooth muscle is hyperreactive, and smoking is a risk factor.","It responds to calcium channel blockers and nitrates; triggers include cocaine and triptans."]],
  ["CA-131","ASSOCIATION","Ischemic heart disease","ST elevation in leads I and aVL with raised troponin — which artery is blocked?","Left circumflex",["Right coronary","Left anterior descending","Posterior descending"],["Leads I, aVL, V5 and V6 look at the lateral wall.","The lateral wall is usually supplied by the left circumflex artery.","Anterior leads (V1–V4) point to the LAD, and inferior leads (II, III, aVF) point to the RCA."]],
  ["CA-132","ASSOCIATION","Congenital & fetal","Septic patient gets a central line; its tip sits in a vessel from the common cardinal veins","Superior vena cava",["Inferior vena cava","Coronary sinus","Azygos vein"],["A central venous catheter tip is placed in the superior vena cava near the right atrium.","The SVC develops from the right common cardinal vein and right anterior cardinal vein.","The coronary sinus comes from the left horn of the sinus venosus."]],
  ["CA-133","MECHANISM","Valves & endocarditis","Late-peaking ejection murmur, soft S2, quieter with Valsalva strain — underlying process","Valve fibroblasts become osteoblast-like",["Fibrillin defect weakens the valve","Myxoid change thickens the leaflets","Immune attack fuses the commissures"],["A late-peaking crescendo-decrescendo murmur with a soft A2 is severe aortic stenosis.","In older adults it comes from calcific degeneration, a process resembling atherosclerosis.","Valve interstitial cells turn into osteoblast-like cells that deposit calcium."]],
  ["CA-134","ASSOCIATION","Arrhythmias","Young man with faints and a family history of sudden death; potassium channel defect — consequence","Ventricular tachycardia and sudden death",["Atrial fibrillation and stroke","Complete heart block and syncope","Dilated heart and heart failure"],["Reduced outward potassium current prolongs the action potential and the QT interval.","Early afterdepolarisations can trigger torsades de pointes.","Torsades can degenerate to ventricular fibrillation and sudden death."]],
  ["CA-135","ASSOCIATION","Ischemic heart disease","Days after a hospital stay she arrests; autopsy shows a slit-like tear in the anterior LV wall","Coronary atherosclerosis",["Infective endocarditis","Hypertrophic cardiomyopathy","Aortic dissection"],["Free wall rupture occurs 5 to 14 days after a transmural MI, when the wall is weakest.","It causes tamponade and sudden death.","The underlying cause is a transmural infarct from coronary atherosclerosis."]],
  ["CA-136","ASSOCIATION","Congenital & fetal","Cyanotic newborn of a diabetic mother; aorta lies in front of and right of the pulmonary artery","Failed septal spiralling",["Endocardial cushion defect","Septum primum defect","Neural crest deficiency in the heart"],["Transposition of the great arteries comes from the aorticopulmonary septum failing to spiral.","The aorta arises from the right ventricle and the pulmonary artery from the left.","Maternal diabetes is a risk factor, and survival depends on a shunt."]],
  ["CA-137","MECHANISM","Cardiac drugs","Dobutamine improves contractility in acute heart failure — mechanism","Gs activation of adenylyl cyclase",["Gq activation of phospholipase C","Gi inhibition of adenylyl cyclase","Inhibition of phosphodiesterase 3"],["Dobutamine mainly stimulates β1 receptors on the heart.","β1 receptors act through Gs to activate adenylyl cyclase and raise cAMP.","cAMP activates protein kinase A, which increases calcium entry and contractility."]],
  ["CA-138","ASSOCIATION","Cardiac physiology","Mitral inflow Doppler: the arrow marks the end of early passive filling — matching sound","Third heart sound",["Fourth heart sound","Opening snap","Midsystolic click"],["An S3 occurs at the end of rapid passive ventricular filling in early diastole.","It is heard when the ventricle is volume-overloaded, as in heart failure.","It can be normal in children, pregnant women and athletes."]],
  ["CA-139","ASSOCIATION","Heart failure & shock","Heart failure with a pleural effusion — thoracentesis fluid compared with plasma","Low lactate dehydrogenase",["High protein content","High lactate dehydrogenase","Low glucose content"],["Heart failure causes a transudate from raised hydrostatic pressure.","Transudates have low protein and low LDH compared with serum.","Light's criteria classify an effusion as an exudate if protein or LDH ratios are high."]],
  ["CA-140","MECHANISM","Cardiomyopathy & tumors","HCM patient much better on high-dose β-blocker — why?","Reduced LV contractility",["Reduced LV preload","Increased LV contractility","Decreased LV afterload"],["In hypertrophic cardiomyopathy, outflow obstruction worsens when the ventricle is small and squeezes hard.","β-blockers reduce contractility and slow the heart, giving more time to fill.","A fuller ventricle pushes the septum and mitral leaflet apart, easing obstruction."]],
  ["CA-141","ASSOCIATION","Congenital & fetal","Newborn with transposition of the great arteries, small PFO and PDA — temporary measure","Enlarging the PFO",["Closing the PDA","Giving supplemental oxygen","Giving indomethacin"],["In transposition, the two circulations run in parallel.","Survival depends on mixing oxygenated and deoxygenated blood through a shunt.","Balloon atrial septostomy enlarges the PFO, and prostaglandin E1 keeps the ductus open."]],
  ["CA-142","ASSOCIATION","Cardiomyopathy & tumors","Embolectomy removes a gelatinous mass of stellate cells in a mucoid matrix — source","Left atrium",["Left ventricle","Right atrium","Mitral valve"],["Myxoma is the commonest primary cardiac tumor in adults.","About 80% arise in the left atrium, often attached to the fossa ovalis.","Myxomas can cause emboli, a tumor plop and syncope by blocking the mitral valve."]],
  ["CA-143","MECHANISM","Heart failure & shock","Car crash with active bleeding and fractures — expected changes","Contractility ↑, baroreceptor firing ↓, ANP ↓",["Contractility ↓, baroreceptor firing ↑, ANP ↑","Contractility ↑, baroreceptor firing ↑, ANP ↓","Contractility ↓, baroreceptor firing ↓, ANP ↑"],["Blood loss lowers arterial pressure, so baroreceptors stretch less and fire less.","This increases sympathetic outflow, raising contractility, heart rate and vascular resistance.","Less atrial stretch reduces ANP release, helping the kidney retain sodium and water."]],
  ["CA-144","ASSOCIATION","Valves & endocarditis","Mitral stenosis with an opening snap — where on the PV loop does the snap occur?","Mitral opening, end of isovolumic relaxation",["Mitral closing, start of isovolumic contraction","Aortic opening, end of isovolumic contraction","Aortic closing, start of isovolumic relaxation"],["An opening snap is the sound of a stiff mitral valve snapping open.","Mitral opening ends isovolumic relaxation and starts ventricular filling.","A shorter interval between S2 and the snap means more severe stenosis."]],
  ["CA-145","ASSOCIATION","Congenital & fetal","Catheter oxygen saturations step up from the right atrium to the right ventricle — physical finding","Holosystolic murmur at left sternal border",["Continuous machinery murmur","Wide, fixed splitting of S2","Diastolic rumble at the apex"],["An oxygen step-up in the right ventricle means a left-to-right shunt at ventricular level.","That shunt is a ventricular septal defect.","A VSD gives a harsh holosystolic murmur at the left lower sternal border."]],
  ["CA-146","ASSOCIATION","Congenital & fetal","Cyanotic newborn with a widely split S1, TR murmur and a huge heart on x-ray","Tricuspid valve displaced toward apex",["Infundibular septum displaced forward","Aorta arising from right ventricle","Pulmonary veins draining to SVC"],["Ebstein anomaly displaces the tricuspid valve downward, \"atrialising\" part of the right ventricle.","It causes tricuspid regurgitation, a huge right atrium and right-to-left shunting through a PFO.","It is associated with lithium exposure in pregnancy and with Wolff-Parkinson-White."]],
  ["CA-147","ASSOCIATION","Valves & endocarditis","Catheter: wedge pressure 36 mm Hg with a normal LV end-diastolic pressure — cause","Mitral stenosis",["Aortic stenosis","Mitral regurgitation","Restrictive cardiomyopathy"],["Wedge pressure reflects left atrial pressure.","A high left atrial pressure with a normal left ventricular diastolic pressure means a gradient across the mitral valve.","That gradient is mitral stenosis, which backs pressure into the lungs."]],
  ["CA-148","MECHANISM","Cardiac physiology","Arterial and venous O₂ contents are known — what else is needed to calculate cardiac output?","Oxygen consumption rate",["Heart rate","Hemoglobin level","Mean arterial pressure"],["The Fick principle: cardiac output = O₂ consumption ÷ (arterial O₂ content − venous O₂ content).","Mixed venous blood is sampled from the pulmonary artery.","With the contents known, only the rate of oxygen consumption is missing."]],
  ["CA-149","SIDE_EFFECT","Cardiac drugs","Elderly woman with AF and HF: confusion, nausea, junctional escape rhythm and high potassium","Digoxin",["Amiodarone","Metoprolol","Diltiazem"],["Digoxin toxicity causes nausea, vomiting, confusion and blurred yellow vision.","It causes many arrhythmias, typically increased automaticity with AV block.","Hyperkalemia signals severe toxicity; renal failure and hypokalemia raise the risk; treat with digoxin-specific antibodies."]],
  ["CA-150","ASSOCIATION","Valves & endocarditis","Fever and weakness; autopsy shows bulky, crumbly mitral vegetations that destroy the cusps — predisposition","Prior valve inflammation and scarring",["Prolonged corticosteroid use","Lupus with antiphospholipid antibodies","Normal valve with high-virulence bacteremia"],["Large friable vegetations that destroy cusps are infective endocarditis.","Previously damaged valves, such as those scarred by rheumatic fever, are the main predisposition for viridans streptococci.","Low-virulence organisms need an abnormal valve to adhere to, whereas S. aureus can infect normal valves."]],
  ["CA-151","MECHANISM","Valves & endocarditis","Rheumatic valve infected by viridans streptococci — the first step in vegetation formation","Fibrin deposition",["Neutrophil infiltration","Bacterial adhesion","Collagen exposure"],["Damaged endothelium promotes deposition of platelets and fibrin, forming a sterile vegetation.","Transient bacteremia (for example after dental work) seeds this nidus.","Viridans streptococci make dextrans that help them stick to fibrin–platelet aggregates."]],
  ["CA-152","MECHANISM","Cardiac drugs","Amiodarone is started after cardioversion — expected ECG changes","Slower rate, longer PR, QRS and QT",["Faster rate, shorter PR, QRS and QT","Slower rate, longer PR, unchanged QT","Same rate, shorter QRS, longer QT"],["Amiodarone has class I, II, III and IV actions.","β and calcium blockade slow the sinus rate and lengthen the PR interval.","Sodium blockade widens the QRS and potassium blockade lengthens the QT."]],
  ["CA-153","SIDE_EFFECT","Cardiac drugs","Heart failure patient with weeks of nausea, diarrhea and altered colour vision — if not corrected, risk of","Arrhythmia",["Pancreatitis","Liver failure","Pulmonary fibrosis"],["Gastrointestinal upset with yellow-green vision suggests chronic digoxin toxicity.","Digoxin raises automaticity and slows AV conduction.","The most dangerous result is ventricular arrhythmia, including bidirectional ventricular tachycardia."]],
  ["CA-154","ASSOCIATION","Heart failure & shock","New hypertension with EF 30% but no congestion — expected mediator pattern","Angiotensin II, norepinephrine, ANP all up",["Angiotensin II and norepinephrine up, ANP down","Angiotensin II, norepinephrine, ANP all down","Angiotensin II down, norepinephrine and ANP up"],["Asymptomatic systolic dysfunction already activates compensatory systems.","Low output switches on the sympathetic system and RAAS to maintain pressure.","Stretched chambers release natriuretic peptides, which partly counter fluid retention."]],
  ["CA-155","ASSOCIATION","Vascular disease","Chest pain and syncope; aortic wall histology shows pools of ground substance in the media","Cystic medial degeneration",["Transmural inflammation","Granulomatous arteritis","Obliterative endarteritis"],["Cystic medial degeneration is loss of elastic fibres and smooth muscle with pools of mucoid material.","It weakens the media and predisposes to aortic dissection and aneurysm.","It is seen with ageing, hypertension and Marfan syndrome."]],
  ["CA-156","MECHANISM","Cardiac drugs","IV drug: renal blood flow up at low dose, cardiac output up at mid dose, output down at high dose","Dopamine",["Dobutamine","Norepinephrine","Isoproterenol"],["Low-dose dopamine acts on D1 receptors, dilating renal vessels.","Moderate doses add β1 stimulation, increasing contractility and output.","High doses act on α1 receptors, causing vasoconstriction that can reduce output."]],
  ["CA-157","MECHANISM","Cardiomyopathy & tumors","Chest pain two days after her husband's death; apical ballooning, clean coronaries, normal weeks later","Catecholamine-induced myocardial stunning",["Plaque rupture with thrombus","Coronary artery dissection","Viral myocarditis"],["Stress (takotsubo) cardiomyopathy follows intense emotional or physical stress.","A catecholamine surge stuns the apical myocardium, which balloons outward.","It mimics an MI but has open coronaries and usually recovers within weeks."]],
  ["CA-158","ASSOCIATION","Cardiac physiology","Left-dominant circulation; stenosis just before the AV nodal artery branch — which vessel?","Left circumflex",["Right coronary","Left anterior descending","Left main"],["The posterior descending artery comes from the dominant coronary artery.","The AV nodal artery usually arises from the dominant artery too.","Most people are right dominant; in left dominance, the left circumflex supplies these."]],
  ["CA-159","ASSOCIATION","Cardiomyopathy & tumors","Systolic murmur at the LSB that softens when he squats — inheritance pattern","Autosomal dominant",["Autosomal recessive","X-linked recessive","Mitochondrial"],["A murmur that softens with squatting (more preload) is hypertrophic cardiomyopathy.","It is usually autosomal dominant, from sarcomere gene mutations such as β-myosin heavy chain or myosin-binding protein C.","First-degree relatives should be screened with echocardiography."]],
  ["CA-160","ASSOCIATION","Cardiomyopathy & tumors","Athlete's sudden death; 580-g heart with asymmetric septal hypertrophy — murmur louder with","Sudden standing",["Squatting","Handgrip","Passive leg raise"],["The HCM murmur gets louder when the left ventricle holds less blood.","Standing and the strain phase of Valsalva reduce preload, increasing obstruction.","Squatting, handgrip and leg raising increase preload or afterload and soften it."]],
  ["CA-161","ASSOCIATION","Cardiomyopathy & tumors","Heart failure; LV biopsy shows pink amorphous material throughout — echo findings","Dilated atrium, thick walls, poor relaxation",["Dilated ventricle, thin walls, low ejection","Normal walls, regurgitant mitral valve","Dilated right ventricle, normal left"],["Cardiac amyloidosis infiltrates the myocardium and stiffens it.","The ventricle stays small with thick walls and impaired relaxation (restrictive cardiomyopathy).","High filling pressures dilate the atria; low ECG voltage despite thick walls is a clue."]],
  ["CA-162","SIDE_EFFECT","Cardiomyopathy & tumors","Lymphoma treated with doxorubicin; months later fatigue and breathlessness — cause","Dilated cardiomyopathy",["Restrictive cardiomyopathy","Constrictive pericarditis","Hypertrophic cardiomyopathy"],["Anthracyclines cause dose-dependent cardiotoxicity through free radical damage to myocytes.","The result is a dilated cardiomyopathy with systolic heart failure.","Dexrazoxane, an iron chelator, reduces the risk; trastuzumab causes a reversible form."]],
  ["CA-163","ASSOCIATION","Valves & endocarditis","Suspected mitral stenosis — best bedside guide to its severity","A2–opening snap interval",["Loudness of the rumble","Intensity of S1","Presence of an S4"],["The opening snap occurs when rising left atrial pressure pops the valve open.","The higher the left atrial pressure, the sooner the valve opens after A2.","So a shorter A2–opening snap interval means more severe stenosis."]],
  ["CA-164","ASSOCIATION","Valves & endocarditis","Boy with fever and heart failure; biopsy shows Aschoff bodies — what came before?","Bacterial pharyngitis",["Viral myocarditis","Bacterial endocarditis","Kawasaki disease"],["Aschoff bodies are the hallmark of rheumatic carditis.","Acute rheumatic fever follows untreated group A streptococcal pharyngitis by 2 to 4 weeks.","Antibodies against streptococcal M protein cross-react with cardiac tissue (molecular mimicry)."]],
  ["CA-165","ASSOCIATION","Congenital & fetal","Newborn with a holosystolic murmur, flat face, protruding tongue and small ears; mother aged 36","Meiotic nondisjunction",["Robertsonian translocation","Mosaic mitotic error","Uniparental disomy"],["These features are Down syndrome (trisomy 21).","About 95% of cases come from maternal meiotic nondisjunction, which rises with maternal age.","Heart defects include endocardial cushion defects (AV canal), VSD and ASD."]],
  ["CA-166","ASSOCIATION","Congenital & fetal","Newborn turns blue during feeds and the harsh murmur disappears — saturation pattern","LA normal, LV falls (shunt at VSD)",["LA falls, LV normal (shunt at atria)","LA and LV both normal","LA and LV both fall equally"],["A harsh ejection murmur that vanishes during a cyanotic spell is tetralogy of Fallot.","During a spell, infundibular spasm forces right ventricular blood across the VSD into the aorta.","Left atrial blood is fully saturated, but left ventricular saturation falls because of the right-to-left shunt."]],
  ["CA-167","ASSOCIATION","Congenital & fetal","Boy with bounding pulses and a continuous murmur below the left clavicle — the ligated vessel came from","Sixth aortic arch",["Fourth aortic arch","Third aortic arch","First aortic arch"],["A continuous machinery murmur and bounding pulses mean patent ductus arteriosus.","The ductus arteriosus and pulmonary arteries come from the sixth aortic arch.","The recurrent laryngeal nerve hooks around the sixth arch derivatives on the left."]],
  ["CA-168","SIDE_EFFECT","Valves & endocarditis","After TAVI, diastolic pressure falls from 76 to 44 and LVEDP rises from 12 to 25 — complication","Aortic regurgitation",["Mitral regurgitation","Cardiac tamponade","Coronary obstruction"],["A leak around or through the new valve lets blood flow back into the ventricle in diastole.","Regurgitant run-off drops aortic diastolic pressure.","The extra volume raises left ventricular end-diastolic pressure."]],
  ["CA-169","ASSOCIATION","Congenital & fetal","Young woman with a stroke; bubbles injected into a vein cross to the left heart — cause","Septum primum and secundum fail to fuse",["Endocardial cushions fail to fuse","Septum primum is absent","Ostium secundum is too large"],["A bubble study crossing to the left side shows a right-to-left shunt.","In a young cryptogenic stroke, this is usually a patent foramen ovale.","A PFO is incomplete fusion of the septum primum and septum secundum after birth."]],
  ["CA-170","ASSOCIATION","Congenital & fetal","Young man dies of a ruptured cerebral aneurysm; autopsy also finds a congenital heart defect","Coarctation of the aorta",["Ventricular septal defect","Tetralogy of Fallot","Transposition of the great arteries"],["Coarctation causes upper body hypertension.","Hypertension and the associated bicuspid aortic valve raise the risk of berry aneurysms.","Other features are rib notching, weak femoral pulses and a delay between radial and femoral pulses."]],
  ["CA-171","ASSOCIATION","Pericardium","Pleuritic chest pain relieved by leaning forward in a woman with a facial rash and proteinuria","Pericardial inflammation",["Pulmonary embolism","Coronary vasospasm","Aortic dissection"],["Sharp pleuritic chest pain relieved by sitting forward is acute pericarditis.","A facial rash and proteinuria point to systemic lupus erythematosus.","Serositis — pericarditis and pleuritis — is a common feature of lupus."]],
  ["CA-172","ASSOCIATION","Congenital & fetal","Infant with tetralogy of Fallot sweats and turns blue during feeds — pressure changes","RV pressure up, PA and LA pressure down",["RV pressure down, PA and LA pressure up","RV, PA and LA pressures all up","RV, PA and LA pressures all down"],["Feeding and crying trigger infundibular spasm in tetralogy of Fallot.","Right ventricular pressure rises behind the obstruction while less blood reaches the lungs.","Less pulmonary return lowers left atrial pressure, and blood shunts right to left across the VSD."]],
  ["CA-173","ASSOCIATION","Valves & endocarditis","Man aware of his heartbeat at night, with bounding femoral pulses and head bobbing","Aortic regurgitation",["Mitral regurgitation","Aortic stenosis","Mitral stenosis"],["A large stroke volume and wide pulse pressure produce a pounding heartbeat.","Head bobbing (de Musset) and bounding pulses (Corrigan) are classic signs.","Causes include a bicuspid valve, aortic root dilation and endocarditis."]],
  ["CA-174","MECHANISM","Cardiac drugs","AF rate-control trial: one drug controls rate at rest but not during exercise","Digoxin",["Metoprolol","Diltiazem","Verapamil"],["Digoxin slows AV conduction mainly by increasing vagal tone.","During exercise, vagal tone falls and sympathetic tone rises, overriding its effect.","β-blockers and calcium channel blockers control the rate during exercise as well."]],
  ["CA-175","ASSOCIATION","Anatomy","Electrophysiology study in sinus rhythm — earliest atrial activation site","Right atrium at the SVC opening",["Right atrium at the coronary sinus","Left atrium at the pulmonary veins","Interatrial septum near the fossa"],["In sinus rhythm the sinoatrial node fires first.","The SA node lies in the crista terminalis where the superior vena cava enters the right atrium.","It is supplied by the sinoatrial nodal artery, usually from the right coronary artery."]],
  ["CA-176","ASSOCIATION","Vascular disease","Superficial thrombophlebitis that heals and recurs in different veins — may signal","Visceral cancer",["Varicose veins","Factor V Leiden","Buerger disease"],["Migratory superficial thrombophlebitis is Trousseau syndrome.","Tumours, especially pancreatic, release procoagulants such as tissue factor and mucin.","Unexplained recurrent thrombophlebitis should prompt a search for occult malignancy."]],
  ["CA-177","ASSOCIATION","Anatomy","Young man with hematuria; left renal vein squeezed between the SMA and aorta — likely to develop","Varicocele",["Hydrocele","Renal artery stenosis","Inguinal hernia"],["Compression of the left renal vein is nutcracker syndrome.","The left gonadal vein drains into the left renal vein, so its pressure rises.","Raised pressure dilates the pampiniform plexus, causing a left varicocele."]],
  ["CA-178","MECHANISM","Cardiac physiology","Long-standing hypertension; low-frequency sound before S1 heard at the apex — why?","Stiff left ventricular wall",["Stiff mitral leaflets","Rapid early ventricular filling","Delayed aortic valve closure"],["The S4 is produced when atrial contraction pushes blood into a noncompliant ventricle.","Concentric hypertrophy from hypertension makes the left ventricle stiff.","It is heard best at the apex with the patient in the left lateral position, at end expiration."]],
  ["CA-179","MECHANISM","Cardiac drugs","After STEMI, a statin lowers total cholesterol from 200 to 140 — which value rose?","LDL receptor density",["HDL cholesterol synthesis","Triglyceride synthesis","Lipoprotein lipase activity"],["Statins inhibit HMG-CoA reductase, lowering cholesterol made in the liver.","Low intracellular cholesterol activates SREBP, which increases LDL receptor expression.","More LDL receptors clear more LDL from the blood."]],
  ["CA-180","MECHANISM","Arrhythmias","Atrial fibrillation at 120/min — what sets the ventricular rate?","AV node refractory period",["SA node firing rate","Atrial muscle refractoriness","Purkinje conduction speed"],["In atrial fibrillation the atria fire chaotically at hundreds of times a minute.","Most impulses arrive while the AV node is refractory and are blocked.","Drugs that lengthen AV nodal refractoriness (β-blockers, calcium channel blockers, digoxin) slow the rate."]],
  ["CA-181","ASSOCIATION","Valves & endocarditis","Fibrous plaques on the tricuspid and pulmonary valves only — which test would diagnose it?","Urinary 5-HIAA",["Urinary metanephrines","Serum chromogranin A","Serum troponin"],["Right-sided valve plaques are carcinoid heart disease.","Serotonin from liver metastases reaches the right heart before the lungs inactivate it.","Carcinoid syndrome is diagnosed by a raised 24-hour urinary 5-HIAA."]],
  ["CA-182","MECHANISM","Cardiac physiology","PV loops during moderate to heavy exercise compared with rest","Bigger EDV and stronger contraction",["Smaller EDV and stronger contraction","Bigger EDV and weaker contraction","Smaller EDV and weaker contraction"],["Exercise raises venous return, increasing end-diastolic volume (preload).","Sympathetic stimulation increases contractility, lowering end-systolic volume.","Both widen the loop and raise stroke volume, while afterload also rises."]],
  ["CA-183","SIDE_EFFECT","Cardiac drugs","AF patient with ischemic cardiomyopathy faints; polymorphic VT on a long QT background — which drug?","Sotalol",["Metoprolol","Diltiazem","Digoxin"],["Polymorphic VT that twists around the baseline with a long QT is torsades de pointes.","Sotalol blocks potassium channels, lengthening the QT.","Its β-blocking effect slows the heart, and bradycardia makes torsades more likely."]],
  ["CA-184","MECHANISM","Valves & endocarditis","Severe aortic stenosis; new atrial fibrillation brings hypotension and pulmonary edema","Sudden fall in LV preload",["Sudden rise in LV afterload","Sudden fall in LV contractility","Sudden rise in venous return"],["The thick, stiff ventricle in aortic stenosis depends on the atrial kick to fill.","Atrial fibrillation removes the atrial contraction and shortens filling time.","Preload falls sharply, cardiac output drops and left atrial pressure rises into the lungs."]],
  ["CA-185","ASSOCIATION","Valves & endocarditis","Boy with irregular jerking movements three months after a sore throat — greatest future risk","Valvular heart disease",["Glomerulonephritis","Chronic arthritis","Epilepsy"],["Sydenham chorea is a major Jones criterion of acute rheumatic fever.","Rheumatic carditis can scar the valves, especially the mitral valve.","Long-term penicillin prophylaxis prevents recurrences that worsen valve damage."]],
  ["CA-186","ASSOCIATION","Cardiac physiology","Cardiac output curve shifts down while the venous return curve is unchanged — cause","Myocardial infarction",["Blood transfusion","Venoconstriction","Arteriolar dilation"],["A lower cardiac output curve with the same venous return curve means reduced contractility.","Losing contracting muscle in an MI produces this shift.","The new operating point has lower output and a higher right atrial pressure."]],
  ["CA-187","MECHANISM","Heart failure & shock","Smoker with right heart failure and high CVP but no leg edema — compensating mechanism","More lymphatic drainage",["Higher plasma oncotic pressure","Lower capillary permeability","Lower arteriolar resistance"],["High venous pressure raises capillary hydrostatic pressure and pushes fluid into tissues.","Lymphatic flow can increase many-fold to carry this fluid away.","Edema appears only when filtration outstrips lymphatic drainage."]],
  ["CA-188","ASSOCIATION","Pericardium","Lung cancer with hypotension, distant heart sounds, pulsus paradoxus and a big heart shadow","CVP high, RA small, LAP high, SV low",["CVP low, RA large, LAP low, SV high","CVP high, RA large, LAP low, SV high","CVP low, RA small, LAP high, SV low"],["Malignant effusion causing cardiac tamponade compresses all chambers equally.","The right atrium collapses, and pressures in all chambers equalise at a high level.","Filling is restricted, so stroke volume and blood pressure fall."]],
  ["CA-189","ASSOCIATION","Vascular disease","CT shows a dissection flap in the ascending aorta — the single most important risk factor","Hypertension",["Smoking","Marfan syndrome","Cocaine use"],["Long-standing hypertension stresses the aortic wall and is the biggest risk factor for dissection.","Type A dissections involve the ascending aorta and need emergency surgery.","In younger patients, connective tissue disorders and bicuspid valves are important causes."]],
  ["CA-190","MECHANISM","Heart failure & shock","Older man faints while shaving — contributing factor","Lower vascular resistance",["Higher vascular resistance","Faster heart rate","Greater contractility"],["Pressure on the carotid sinus while shaving triggers carotid sinus hypersensitivity.","An exaggerated baroreflex causes vasodilation and bradycardia.","Both lower cardiac output and blood pressure enough to cause syncope."]],
  ["CA-191","MECHANISM","Vascular disease","Claudication from peripheral artery disease — drug that dilates arteries and inhibits platelets","Cilostazol",["Clopidogrel","Aspirin","Pentoxifylline"],["Cilostazol inhibits phosphodiesterase 3.","Higher cAMP in platelets inhibits aggregation, and in smooth muscle it causes vasodilation.","It improves walking distance in claudication but is contraindicated in heart failure."]],
  ["CA-192","ASSOCIATION","Congenital & fetal","Premature infant with a continuous murmur and bounding pulses — changes vs a normal newborn","LV output ↑, SVR ↓, LA filling ↑",["LV output ↓, SVR ↑, LA filling ↓","LV output ↑, SVR ↑, LA filling ↓","LV output ↓, SVR ↓, LA filling ↑"],["A patent ductus arteriosus lets aortic blood run off into the pulmonary artery.","The run-off lowers effective systemic vascular resistance and widens the pulse pressure.","Extra pulmonary flow returns to the left atrium, and the left ventricle pumps more to compensate."]],
  ["CA-193","ASSOCIATION","Valves & endocarditis","Young woman dies of MI; small sterile vegetations on both mitral surfaces and wire-loop glomeruli","Systemic lupus erythematosus",["Acute rheumatic fever","Infective endocarditis","Carcinoid syndrome"],["Libman-Sacks endocarditis is small sterile vegetations on both sides of a valve.","Wire-loop lesions in the glomeruli are diffuse proliferative lupus nephritis.","Lupus also accelerates coronary atherosclerosis in young women."]],
  ["CA-194","MECHANISM","Cardiac physiology","Coronary flow barely changes as pressure rises and follows metabolic demand — main mediators","Nitric oxide and adenosine",["Angiotensin II and endothelin","Norepinephrine and vasopressin","Thromboxane and serotonin"],["Coronary flow is closely matched to oxygen demand.","Metabolites such as adenosine and nitric oxide dilate coronary arterioles when demand rises.","This metabolic control allows the heart to extract a high fraction of oxygen at all times."]],
  ["CA-195","MECHANISM","Ischemic heart disease","Elderly heart with yellow-brown granules in myocyte cytoplasm — how do they form?","Lipid peroxidation",["Iron overload","Bilirubin deposition","Melanin synthesis"],["The granules are lipofuscin, a wear-and-tear pigment.","Lipofuscin forms from peroxidation of membrane lipids by free radicals.","It builds up in the heart, liver and brain with age and with atrophy."]],
  ["CA-196","MECHANISM","Cardiac drugs","Triglycerides 675 mg/dL; fenofibrate is started — how does it help?","Less hepatic VLDL production",["Less intestinal cholesterol uptake","More bile acid excretion","Less hepatic cholesterol synthesis"],["Fibrates activate PPAR-α, which upregulates lipoprotein lipase.","They reduce hepatic VLDL production and increase triglyceride clearance.","Side effects include myopathy (especially with statins) and cholesterol gallstones."]],
  ["CA-197","MECHANISM","Cardiac drugs","Hypertensive heart failure improves with a nitroglycerin infusion — intracellular event","Myosin light chain dephosphorylation",["Myosin light chain phosphorylation","Calcium release from sarcoplasmic reticulum","Protein kinase C activation"],["Nitroglycerin releases nitric oxide, which activates guanylyl cyclase and raises cGMP.","cGMP activates myosin light chain phosphatase, which dephosphorylates myosin.","Dephosphorylated myosin cannot bind actin, so the smooth muscle relaxes."]],
  ["CA-198","MECHANISM","Cardiac drugs","After MI, low HDL and normal LDL — best lipid drug to prevent events","HMG-CoA reductase inhibitor",["Niacin","Fibrate","Bile acid sequestrant"],["Statins reduce cardiovascular events and death after MI regardless of baseline lipids.","They lower LDL and stabilise plaques, and also have anti-inflammatory effects.","Drugs that raise HDL, such as niacin, have not been shown to reduce events."]],
  ["CA-199","ASSOCIATION","Vascular disease","Varicose veins, leg edema and brown skin discolouration — pigment source","Hemosiderin",["Melanin","Lipofuscin","Bilirubin"],["Chronic venous insufficiency causes venous hypertension in the legs.","Red cells leak into the skin and are broken down into hemosiderin.","The result is brown stasis dermatitis, often near the ankles."]],
  ["CA-200","MECHANISM","Cardiac drugs","Chest pain and tachycardia after stopping a β-blocker abruptly — mechanism","β-receptor upregulation",["α-receptor upregulation","β-receptor downregulation","Catecholamine depletion"],["Long-term β-blockade causes the cell to make more β receptors.","When the drug is stopped suddenly, normal catecholamines act on extra receptors.","This exaggerated response can trigger angina or MI, so β-blockers are tapered."]],
  ["CA-201","MECHANISM","Vascular disease","Aortic dissection treated at once with IV esmolol — main purpose","Slower LV contraction velocity",["Higher LV contractility","Lower venous return","Wider coronary arteries"],["Heart rate and the force of ejection (dP/dt) drive the dissection forward.","β-blockers reduce both, lowering shear stress on the aortic wall.","They are given before vasodilators to avoid reflex tachycardia."]],
  ["CA-202","ASSOCIATION","Congenital & fetal","Infant with heart failure, a holosystolic murmur and a thrill at the LLSB — pressure changes","RA same, RV ↑, LA ↑, LV ↑",["RA ↑, RV ↑, LA same, LV same","RA same, RV ↓, LA ↑, LV ↓","RA ↓, RV same, LA ↓, LV ↑"],["A large VSD shunts blood left to right in systole.","The right ventricle and pulmonary circulation are pressurised, raising right ventricular pressure.","Extra blood returns to the left atrium and ventricle, raising their pressures and volumes."]],
  ["CA-383","ASSOCIATION","Congenital & fetal","Distressed post-term newborn with lower saturation in the foot than the right hand","Right-to-left shunt through the PDA",["Left-to-right shunt through the PDA","Right-to-left shunt through the PFO","Mixing through a large VSD"],["Differential cyanosis means deoxygenated blood is entering the aorta after the right subclavian.","This happens when high pulmonary pressure drives blood right to left across a patent ductus.","Persistent pulmonary hypertension of the newborn is associated with post-term birth and meconium aspiration."]],
  ["CA-384","MECHANISM","Arrhythmias","Paroxysmal AF four years ago has now become persistent — what drives the progression?","Atrial structural remodelling",["Increased vagal tone","Sinus node degeneration","Accessory pathway conduction"],["Atrial fibrillation remodels the atria electrically and structurally.","Fibrosis and dilation create more reentry circuits that sustain the arrhythmia.","Hence \"AF begets AF\", and early rhythm control can slow progression."]],
  ["CA-385","ASSOCIATION","Anatomy","AV node ablation is planned — where should the catheter tip go?","Septum near coronary sinus opening",["Lateral right atrium near the SVC","Left atrium near the pulmonary veins","Right ventricular apex"],["The AV node lies in the triangle of Koch in the right atrium.","Its boundaries are the septal leaflet of the tricuspid valve, the coronary sinus opening and the tendon of Todaro.","After AV nodal ablation, a permanent ventricular pacemaker is needed."]],
  ["CA-386","ASSOCIATION","Valves & endocarditis","Fever, new apical holosystolic murmur and flat red painless palm lesions — the lesions are","Septic microemboli",["Immune complex deposits","Small vessel vasculitis","Capillary hemorrhages"],["Janeway lesions are painless red macules on the palms and soles.","They come from septic microemboli with small abscesses.","Osler nodes, by contrast, are painful and immune mediated."]],
  ["CA-387","MECHANISM","Cardiac drugs","Decompensated cardiomyopathy treated with a milrinone infusion — expected response","Arterial and venous dilation",["Arterial and venous constriction","Slowed heart rate","Decreased contractility"],["Milrinone inhibits phosphodiesterase 3, raising cAMP.","In the heart, more cAMP increases contractility.","In vascular smooth muscle, more cAMP causes arterial and venous dilation (an inodilator)."]],
  ["CA-388","SIDE_EFFECT","Cardiac drugs","Stable angina; aspirin causes wheezing — best alternative","Clopidogrel",["Warfarin","Dipyridamole","Heparin"],["Aspirin can trigger bronchospasm in aspirin-exacerbated respiratory disease.","Clopidogrel blocks the platelet P2Y12 ADP receptor and is the usual alternative.","Clopidogrel is a prodrug activated by CYP2C19, so poor metabolisers respond less."]],
  ["CA-389","ASSOCIATION","Ischemic heart disease","Five days after anterolateral STEMI: sudden shock, raised JVP, clear lungs, no murmur, then death","Blood in the pericardial space",["Rupture of a papillary muscle","Rupture of the septum","Dressler syndrome"],["Free wall rupture occurs 5 to 14 days after MI, when macrophages have softened the infarct.","Blood fills the pericardium and causes tamponade.","Unlike papillary muscle or septal rupture, it produces no new murmur."]],
  ["CA-390","ASSOCIATION","Heart failure & shock","Teen with wheeze, rash and shock after eating — hemodynamic pattern","CVP, wedge and SVR all low",["CVP and wedge high, SVR low","CVP, wedge and SVR all high","CVP and wedge low, SVR high"],["Anaphylaxis is a distributive shock.","Histamine and other mediators cause widespread vasodilation and capillary leak.","Low SVR and low filling pressures result; give IM epinephrine first."]],
  ["CA-391","ASSOCIATION","Anatomy","CABG with a saphenous vein graft — where is the vein accessed?","Just inferolateral to pubic tubercle",["Just posterior to medial malleolus","In the popliteal fossa","Just lateral to femoral artery"],["The great saphenous vein joins the femoral vein at the saphenous opening.","The opening lies about 3 to 4 cm inferolateral to the pubic tubercle.","At the ankle the vein runs in front of the medial malleolus."]],
  ["CA-392","MECHANISM","Cardiac drugs","Acute heart failure treated with sodium nitroprusside — change in the PV loop","Lower preload and afterload, same SV",["Higher preload and afterload, same SV","Lower preload, higher afterload","Higher preload, lower SV"],["Nitroprusside releases nitric oxide and dilates arteries and veins equally.","Venodilation lowers preload; arterial dilation lowers afterload.","Stroke volume is maintained at lower pressures; prolonged use risks cyanide toxicity."]],
  ["CA-393","SIDE_EFFECT","Cardiac drugs","LDL 190 mg/dL despite lifestyle change — test before starting a statin","Liver transaminases",["Serum creatinine","Serum potassium","Thyroid antibodies"],["Statins can raise transaminases and rarely cause hepatitis.","A baseline liver test is checked before starting.","Creatine kinase is checked only if muscle symptoms develop."]],
  ["CA-394","ASSOCIATION","Arrhythmias","Elderly woman near-faints; ECG shows slow sinus rhythm with dropped P waves — degenerated cells are in","Right atrial wall",["Interventricular septum","Left atrial wall","Bundle of His"],["Sick sinus syndrome is age-related degeneration and fibrosis of the sinoatrial node.","The SA node lies in the right atrial wall at the opening of the superior vena cava.","It causes bradycardia, pauses and sometimes alternating tachycardia; pacemakers treat it."]],
  ["CA-395","ASSOCIATION","Heart failure & shock","Which substance is higher in the pulmonary vein than in the pulmonary artery?","Angiotensin II",["Bradykinin","Serotonin","Prostaglandin E₂"],["ACE is concentrated on the pulmonary capillary endothelium.","Angiotensin I is converted to angiotensin II as blood passes through the lungs.","The same enzyme breaks down bradykinin, so bradykinin falls across the lungs."]],
  ["CA-396","ASSOCIATION","Anatomy","Abdominal CT: the arrow marks a large vein to the right of the aorta — what is true of it?","Formed by the common iliac veins",["Drains directly into the portal vein","Lies to the left of the aorta","Receives the left gonadal vein directly"],["The inferior vena cava forms at L5 from the right and left common iliac veins.","It runs up to the right of the aorta to the right atrium.","The left gonadal vein drains into the left renal vein rather than directly into the IVC."]],
  ["CA-397","MECHANISM","Hypertension","Metoprolol prescribed for migraine will also lower her blood pressure — main mechanism","Less circulating renin",["Less venous return","More nitric oxide release","More sodium excretion"],["β1 receptors on juxtaglomerular cells stimulate renin release.","β1 blockers reduce renin, angiotensin II and aldosterone.","They also reduce heart rate and cardiac output."]],
  ["CA-398","MECHANISM","Cardiac drugs","Pure adrenergic agonist raises BP while heart rate falls — expected effect","Slower AV node conduction",["Faster AV node conduction","Shorter AV node refractoriness","Faster SA node firing"],["A rise in pressure with a fall in heart rate is the pattern of a selective α1 agonist such as phenylephrine.","The baroreceptor reflex increases vagal tone to the heart.","Vagal tone slows the SA node and slows conduction through the AV node."]],
  ["CA-399","ASSOCIATION","Heart failure & shock","Heavy drinker dies gasping; lungs show engorged capillaries and pink acellular fluid in alveoli","Pulmonary edema",["Lobar pneumonia","Diffuse alveolar damage","Pulmonary hemorrhage"],["Engorged capillaries with pink, protein-poor fluid in the alveoli is cardiogenic pulmonary edema.","It is worst at the lung bases, where hydrostatic pressure is highest.","Chronic alcohol use can cause dilated cardiomyopathy and left heart failure."]],
  ["CA-400","MECHANISM","Cardiac drugs","HFrEF (EF 35%) after stabilisation — drug that improves long-term survival","Carvedilol",["Digoxin","Furosemide","Amlodipine"],["Certain β-blockers (carvedilol, metoprolol succinate, bisoprolol) reduce mortality in HFrEF.","They block chronic sympathetic activation, which damages myocytes and causes arrhythmias.","Digoxin and loop diuretics relieve symptoms but do not improve survival."]],
  ["CA-401","MECHANISM","Cardiac physiology","Upper GI bleed treated with 2 L of saline — which value rises?","End-diastolic sarcomere length",["Afterload","Heart rate","Myocardial contractility"],["Fluids raise venous return and preload.","More preload stretches myocytes, lengthening sarcomeres toward their optimal length.","Better actin–myosin overlap increases force and stroke volume (Frank-Starling)."]],
  ["CA-402","ASSOCIATION","Vascular disease","Elderly man with weeks of cough, dysphagia and hoarseness, then chest pain, shock and PEA arrest","Ruptured thoracic aortic aneurysm",["Esophageal carcinoma","Massive pulmonary embolism","Ruptured papillary muscle"],["A growing thoracic aneurysm compresses nearby structures.","It causes cough (trachea), dysphagia (esophagus) and hoarseness (left recurrent laryngeal nerve).","Rupture causes sudden pain, hemorrhagic shock and death."]],
  ["CA-403","MECHANISM","Cardiac physiology","After an inferior MI, the left ventricle stays weak but the right ventricle recovers fully — why?","RV is perfused in systole and diastole",["RV has thicker walls than LV","RV has more collateral arteries","RV muscle uses less glucose"],["The left ventricle is perfused mainly in diastole because systolic compression stops flow.","The low-pressure right ventricle is perfused throughout the cardiac cycle.","It also has lower oxygen demand, so it usually recovers after infarction."]],
  ["CA-404","MECHANISM","Congenital & fetal","Teen with leg cramps, strong radial but weak foot pulses and a murmur between the shoulder blades","Flow through collateral vessels",["Flow through a patent ductus","Turbulence at the aortic valve","Flow across a septal defect"],["Upper limb hypertension with weak leg pulses is coarctation of the aorta.","Intercostal arteries enlarge to carry blood around the narrowing.","Flow through these collaterals makes a continuous murmur over the back and notches the ribs."]],
  ["CA-405","ASSOCIATION","Cardiac physiology","Orthopnea and an extra sound just after S2 at the apex — what makes it louder?","Listening at end expiration",["Listening during inspiration","Having him stand up","Doing a Valsalva maneuver"],["A low-pitched sound just after S2 is an S3, from rapid filling of a volume-overloaded ventricle.","Left-sided sounds are heard best at the apex with the bell, patient on the left side.","At end expiration the heart lies closest to the chest wall, making the sound louder."]],
  ["CA-406","MECHANISM","Cardiac drugs","Dofetilide keeps him in sinus rhythm — which action potential phase is mainly affected?","Phase 3",["Phase 0","Phase 2","Phase 4"],["Class III drugs block outward potassium currents.","Phase 3 is the repolarisation phase driven by those currents.","Prolonging phase 3 lengthens the refractory period and the QT interval."]],
  ["CA-407","ASSOCIATION","Cardiomyopathy & tumors","Heart failure soon after childbirth: displaced apex and an S3 — LV changes","EF down, compliance up",["EF up, compliance down","EF down, compliance down","EF normal, compliance down"],["Heart failure in late pregnancy or the months after delivery is peripartum cardiomyopathy.","It is a dilated cardiomyopathy with a large, weak ventricle.","A dilated ventricle is more compliant but has a reduced ejection fraction."]],
  ["CA-409","MECHANISM","Congenital & fetal","Infant with tetralogy of Fallot has a hematocrit of 52% — why?","Reduced pulmonary blood flow",["Increased plasma volume loss","Bone marrow neoplasia","Increased red cell lifespan"],["Right ventricular outflow obstruction limits blood flow to the lungs.","Right-to-left shunting adds deoxygenated blood to the systemic circulation.","Chronic hypoxemia stimulates erythropoietin, causing secondary polycythemia."]],
  ["CA-408","ASSOCIATION","Valves & endocarditis","Dies playing tennis from a ruptured ascending aortic aneurysm; LV dilated with normal wall thickness","Aortic regurgitation",["Aortic stenosis","Hypertrophic cardiomyopathy","Restrictive cardiomyopathy"],["A dilated left ventricle with walls of normal thickness is eccentric hypertrophy, the response to volume overload.","An ascending aortic aneurysm widens the aortic root, so the valve leaflets cannot meet and blood leaks back in diastole.","Pressure overload, as in aortic stenosis, would instead cause concentric hypertrophy with thick walls and a small cavity."]],
  ["CA-410","MECHANISM","Ischemic heart disease","Plaque ruptures a year after stable symptoms, causing an MI — which enzyme weakened the cap?","Matrix metalloproteinases",["Lipoprotein lipase","Lysyl oxidase","Nitric oxide synthase"],["Macrophages in the plaque release matrix metalloproteinases.","These enzymes degrade collagen in the fibrous cap, thinning it.","A thin cap ruptures, exposing thrombogenic material and triggering an occlusive clot."]],
  ["CA-411","ASSOCIATION","Vascular disease","Child with 5 days of fever, red cracked lips, strawberry tongue and swollen hands — greatest risk","Coronary artery aneurysm",["Renal artery aneurysm","Acute glomerulonephritis","Aortic dissection"],["Fever with conjunctivitis, oral changes, rash, swollen extremities and a neck node is Kawasaki disease.","Medium-vessel vasculitis can cause coronary aneurysms, thrombosis and MI.","IV immunoglobulin and aspirin reduce the risk of coronary aneurysms."]],
  ["CA-412","SIDE_EFFECT","Hypertension","On lisinopril with K⁺ 5.3 mEq/L and BP still high — which drug should be avoided?","Eplerenone",["Amlodipine","Chlorthalidone","Hydrochlorothiazide"],["Eplerenone blocks aldosterone, so potassium is retained.","ACE inhibitors also raise potassium by lowering aldosterone.","Combining them with an already raised potassium risks dangerous hyperkalemia."]],
  ["CA-413","MECHANISM","Valves & endocarditis","Healthy elderly man's autopsy shows heavy aortic valve calcification — what came first?","Chronic cell injury",["Hypercalcemia","Acute inflammation","Infective endocarditis"],["Calcification of an ageing valve with normal serum calcium is dystrophic calcification.","Dystrophic calcification occurs in damaged or dead tissue.","Years of mechanical stress injure valve cells, which then calcify."]],
  ["CA-414","MECHANISM","Cardiac drugs","Verapamil reduces his palpitations — effect on pacemaker cells","Slower phase 4 depolarisation",["Faster phase 0 upstroke","Shorter refractory period","Faster repolarisation"],["Pacemaker cells depend on calcium currents for phase 4 and phase 0.","Verapamil blocks L-type calcium channels, slowing spontaneous depolarisation.","It also slows AV nodal conduction, which helps prevent reentrant tachycardias."]],
  ["CA-415","ASSOCIATION","Vascular disease","Screening for abdominal aortic aneurysm — highest risk group","Men who smoke",["Women who smoke","Diabetic men","Young hypertensive women"],["Smoking is the strongest modifiable risk factor for abdominal aortic aneurysm.","Male sex and age over 65 also greatly raise the risk.","Men aged 65 to 75 who have ever smoked are screened once with ultrasound; diabetes is protective."]],
  ["CA-416","MECHANISM","Ischemic heart disease","Old healed infarct in the LV wall — which substance directly promotes the scar?","Transforming growth factor-β",["Tumor necrosis factor-α","Interleukin-1","Interferon-γ"],["After an infarct, macrophages clear debris and release growth factors.","TGF-β stimulates fibroblasts to make collagen and inhibits its breakdown.","Over weeks, granulation tissue is replaced by a dense collagen scar."]],
  ["CA-417","ASSOCIATION","Congenital & fetal","Preterm infant with a PDA; catheter blood gases — where is PaO₂ higher than normal?","Pulmonary artery",["Right atrium","Right ventricle","Left ventricle"],["After birth, a patent ductus shunts oxygenated aortic blood into the pulmonary artery.","The oxygen step-up appears in the pulmonary artery.","Right atrial and right ventricular blood remains normally deoxygenated."]],
  ["CA-418","ASSOCIATION","Ischemic heart disease","Dobutamine stress echo: apical wall weakens and EF drops, then normalises minutes after stopping","Supply–demand mismatch from fixed stenosis",["Acute plaque rupture with thrombus","Coronary vasospasm without stenosis","Myocardial stunning after infarction"],["Dobutamine raises heart rate and contractility, increasing oxygen demand.","A fixed stenosis cannot increase flow enough, so the territory becomes ischemic.","The temporary wall motion abnormality reverses at rest, the pattern of stable angina."]],
  ["CA-419","MECHANISM","Cardiomyopathy & tumors","HCM patient with exertional dyspnea — how does verapamil help?","Longer diastolic filling time",["Lower venous return","Stronger contraction","Lower afterload"],["Verapamil slows the heart rate.","A slower rate gives the stiff ventricle more time to fill in diastole.","A fuller ventricle reduces outflow obstruction and improves relaxation."]],
  ["CA-420","MECHANISM","Cardiac physiology","Healthy man followed for 30 years keeps a normal EF into his 80s — what preserves it?","Hypertrophy of myocytes",["Hyperplasia of myocytes","Larger LV cavity","Faster resting heart rate"],["With age, some myocytes die and are not replaced.","The remaining myocytes enlarge, causing mild concentric hypertrophy.","This keeps contraction and ejection fraction normal despite fewer cells."]],
  ["CA-421","ASSOCIATION","Hypertension","Untreated healthy people at age 80 vs age 50 — change in blood pressure","Systolic up, diastolic down, pulse pressure up",["Systolic up, diastolic up, pulse pressure same","Systolic same, diastolic down, pulse pressure up","Systolic down, diastolic down, pulse pressure down"],["The aorta stiffens as elastin is replaced by collagen.","A stiff aorta raises systolic pressure and lets diastolic pressure fall.","The result is a wider pulse pressure and isolated systolic hypertension."]],
  ["CA-422","ASSOCIATION","Arrhythmias","Boy with bilateral sensorineural deafness and a QTc of 520 ms — defective structure","Potassium channels",["Sodium channels","Calcium channels","Gap junctions"],["Congenital deafness with a long QT is Jervell and Lange-Nielsen syndrome.","It is autosomal recessive, from mutations in KCNQ1 or KCNE1 potassium channel genes.","The same channels help make endolymph in the inner ear, which explains the deafness."]],
  ["CA-423","MECHANISM","Congenital & fetal","Cyanotic newborn with tetralogy of Fallot — the drug to give immediately","Keeps the ductus open",["Closes the ductus","Lowers pulmonary resistance","Raises heart rate"],["In severe tetralogy, pulmonary blood flow depends on the ductus arteriosus.","Prostaglandin E1 (alprostadil) keeps the ductus open.","Indomethacin, which closes the ductus, would be harmful here."]],
  ["CA-424","MECHANISM","Congenital & fetal","Healthy term newborn — changes from fetal to newborn circulation","SVR up, PVR down, LV share up",["SVR down, PVR up, LV share down","SVR up, PVR up, LV share same","SVR down, PVR down, LV share up"],["Clamping the cord removes the low-resistance placenta, so systemic resistance rises.","Breathing expands and oxygenates the lungs, so pulmonary resistance falls.","Flow across the ductus reverses and the left ventricle becomes the sole systemic pump."]],
  ["CA-425","ASSOCIATION","Anatomy","Right middle lobe pneumonia blurs the right heart border — which chamber forms that border?","Right atrium",["Right ventricle","Left atrium","Superior vena cava"],["On a frontal chest x-ray the right heart border is formed mainly by the right atrium.","The right middle lobe sits against this border.","Consolidation there obscures the border (silhouette sign)."]],
  ["CA-426","MECHANISM","Cardiac drugs","Endothelium beside a coronary thrombus releases a substance that limits platelet aggregation","Prostacyclin",["Thromboxane A₂","von Willebrand factor","Endothelin-1"],["Healthy endothelium secretes prostacyclin (PGI₂).","Prostacyclin raises platelet cAMP, inhibiting aggregation, and causes vasodilation.","Thromboxane A₂ from platelets has the opposite effects."]],
  ["CA-427","ASSOCIATION","Arrhythmias","Elderly man with untreated AF and a dilated left atrium wakes with a stroke — source of the clot","Left atrial appendage",["Left ventricular apex","Carotid bifurcation","Mitral valve leaflet"],["In atrial fibrillation the atria do not contract, so blood stagnates.","The left atrial appendage is the commonest site of clot formation.","Anticoagulation (guided by the CHA₂DS₂-VASc score) prevents these strokes."]],
  ["CA-428","MECHANISM","Cardiac physiology","Acetylcholine dilates healthy coronary arteries — which amino acid is the source?","Arginine",["Tyrosine","Tryptophan","Glutamine"],["Acetylcholine acts on endothelial receptors to activate nitric oxide synthase.","NO synthase makes nitric oxide from L-arginine.","NO raises cGMP in smooth muscle, causing vasodilation; diseased endothelium may constrict instead."]],
  ["CA-429","ASSOCIATION","Congenital & fetal","Teen with a parasternal lift, fixed split S2 and an ejection murmur at the LUSB — echo shows","RA and RV enlarged, LA and LV normal",["LA and LV enlarged, RA and RV normal","All four chambers enlarged","RV enlarged, all others normal"],["An atrial septal defect shunts blood left to right at the atrial level.","The extra volume flows through the right atrium, right ventricle and pulmonary artery.","These right-sided chambers dilate while the left-sided chambers stay normal."]],
  ["CA-430","ASSOCIATION","Anatomy","Stab wound at the left 5th intercostal space, midclavicular line, blade angled laterally","Left lung",["Left ventricle","Right ventricle","Left atrium"],["The cardiac apex lies near the left 5th intercostal space at the midclavicular line.","A blade angled outward, away from the heart, passes into the lung.","The result is a pneumothorax or hemothorax rather than a cardiac injury."]],
  ["CA-431","MECHANISM","Cardiac physiology","Stress test pushes heart rate to 150 — main factor limiting LV blood supply","Duration of diastole",["Aortic diastolic pressure","Coronary vessel diameter","Blood oxygen content"],["The left ventricle is perfused mainly in diastole.","As heart rate rises, diastole shortens much more than systole.","Shorter diastole limits subendocardial perfusion, which is why tachycardia provokes ischemia."]],
  ["CA-432","ASSOCIATION","Valves & endocarditis","Recording at the left sternal border: high-pitched decrescendo diastolic murmur","Aortic regurgitation",["Mitral stenosis","Aortic stenosis","Mitral regurgitation"],["A decrescendo early diastolic murmur at the left sternal border is aortic regurgitation.","Blood leaks back into the left ventricle as soon as the aortic valve closes.","Chronic aortic regurgitation causes eccentric hypertrophy and a wide pulse pressure."]],
  ["CA-433","MECHANISM","Cardiac drugs","Septic shock; infusion raises SVR and BP while heart rate falls — which drug?","Phenylephrine",["Dobutamine","Epinephrine","Isoproterenol"],["Phenylephrine is a selective α1 agonist that constricts arterioles.","Higher resistance raises blood pressure.","The baroreflex then slows the heart, since phenylephrine has no β1 effect."]],
  ["CA-434","ASSOCIATION","Valves & endocarditis","Young woman with a midsystolic click and late murmur that disappears on squatting — tissue at fault","Connective tissue",["Cardiac muscle","Conduction tissue","Vascular endothelium"],["A midsystolic click with a late systolic murmur is mitral valve prolapse.","It comes from myxomatous degeneration of the leaflets and chordae.","It is associated with Marfan and Ehlers-Danlos syndromes and polycystic kidney disease."]],
  ["CA-435","ASSOCIATION","Arrhythmias","Healthy man with an irregularly irregular pulse of 138 after a party — ECG strip","No P waves, irregular R–R intervals",["Sawtooth flutter waves at 300","Regular rhythm with no P waves","Wide QRS at a regular rate"],["Binge drinking can trigger atrial fibrillation (holiday heart).","Chaotic atrial activity replaces P waves with a wavy baseline.","The AV node conducts irregularly, so R–R intervals vary unpredictably."]],
  ["CA-436","MECHANISM","Heart failure & shock","Teen faints while standing in the heat after feeling warm and nauseated — cause","Surge in parasympathetic output",["Surge in sympathetic output","Fall in blood volume","Fast ventricular arrhythmia"],["Vasovagal syncope is the commonest cause of fainting in young people.","Prolonged standing or emotion triggers a reflex with high vagal tone and sympathetic withdrawal.","Bradycardia and vasodilation reduce cerebral perfusion; warning signs include warmth, nausea and sweating."]],
  ["CA-437","SIDE_EFFECT","Hypertension","Elderly man started on a BP drug develops ankle swelling — which drug?","Amlodipine",["Lisinopril","Losartan","Chlorthalidone"],["Dihydropyridine calcium channel blockers dilate arterioles more than venules.","This raises capillary hydrostatic pressure, causing peripheral edema.","Other side effects include flushing, headache and reflex tachycardia."]],
  ["CA-438","ASSOCIATION","Cardiac physiology","Healthy pregnancy at 30 weeks — cardiac changes vs the nonpregnant state","Output up, preload up, afterload down",["Output up, preload down, afterload up","Output down, preload up, afterload down","Output same, preload up, afterload up"],["Blood volume rises by about 40 to 50% in pregnancy, increasing preload.","Progesterone and the placenta lower systemic vascular resistance (afterload).","Cardiac output rises by about 30 to 50%, peaking in the early third trimester."]],
  ["CA-439","ASSOCIATION","Arrhythmias","Flank pain, hematuria, high LDH and a wedge-shaped kidney defect on CT — likely source","Atrial fibrillation",["Renal artery atherosclerosis","Renal vein thrombosis","Kidney stone obstruction"],["A wedge-shaped perfusion defect with high LDH is a renal infarct.","Most renal infarcts are embolic, usually from a clot in the left atrium.","Atrial fibrillation is the commonest source of systemic emboli."]],
  ["CA-440","ASSOCIATION","Arrhythmias","Faints while working; slow regular narrow-QRS rhythm with P waves unrelated to QRS — pacemaker site","His bundle",["Purkinje fibres","Ventricular muscle","Sinoatrial node"],["P waves completely dissociated from QRS complexes is third-degree AV block.","A narrow QRS means the escape rhythm starts above the bundle branches.","Junctional (His bundle) escape runs at 40 to 60/min; ventricular escape is slower with a wide QRS."]],
  ["CA-441","SIDE_EFFECT","Cardiac drugs","Elderly man faints with new constipation and second-degree AV block two weeks after a new drug","Diltiazem",["Amlodipine","Hydralazine","Lisinopril"],["Non-dihydropyridine calcium channel blockers slow the SA and AV nodes.","They can cause bradycardia and AV block, especially with β-blockers.","Constipation is a classic side effect, particularly of verapamil and diltiazem."]],
  ["CA-442","ASSOCIATION","Valves & endocarditis","Injection drug user with fever, a new murmur and nodular lung opacities — echo shows","Tricuspid regurgitation",["Mitral stenosis","Aortic stenosis","Pulmonic stenosis"],["Injection drug use causes right-sided endocarditis, usually of the tricuspid valve.","Vegetations destroy the leaflets, causing regurgitation.","Septic emboli to the lungs produce nodular, often cavitating opacities."]],
  ["CA-443","SIDE_EFFECT","Cardiac drugs","Endocarditis treated with an IV antibiotic; itching and a flushing rash start during the infusion","Vancomycin",["Gentamicin","Ceftriaxone","Nafcillin"],["Rapid vancomycin infusion directly activates mast cells.","Histamine release causes flushing, itching and hypotension (vancomycin infusion reaction).","It is not a true allergy; slowing the infusion and giving antihistamines prevents it."]],
  ["CA-444","ASSOCIATION","Arrhythmias","Found unresponsive under a tree in a storm with fern-like skin marks — primary cause of death","Cardiac arrhythmia",["Pulmonary contusion","Hypovolemic shock","Intracranial bleed"],["Lichtenberg figures are fern-like marks typical of a lightning strike.","A massive direct current causes asystole or ventricular fibrillation.","Respiratory arrest from brainstem injury can follow, so prolonged ventilation may help."]],
  ["CA-445","SIDE_EFFECT","Cardiac drugs","PSVT stopped instantly by a rapid IV drug that causes flushing and chest burning","Adenosine",["Verapamil","Esmolol","Amiodarone"],["Adenosine acts on A1 receptors to transiently block the AV node, breaking reentry.","It has a half-life of seconds, so side effects are brief.","It causes flushing, chest burning and a sense of doom; theophylline and caffeine block it."]],
  ["CA-446","ASSOCIATION","Arrhythmias","Accessory pathway bypasses the AV node — which ECG part changes in sinus rhythm?","PR segment",["ST segment","QT interval","T wave"],["An accessory pathway (bundle of Kent) conducts faster than the AV node.","Early ventricular activation shortens the PR interval.","It also slurs the start of the QRS, producing a delta wave."]],
  ["CA-447","SIDE_EFFECT","Hypertension","New drug selectively relaxes arteriolar smooth muscle only — expected adverse effect","Sodium and fluid retention",["Hyperkalemia","Dry cough","Bradycardia"],["Direct arteriolar dilators (hydralazine, minoxidil) lower blood pressure suddenly.","Reflex sympathetic activation causes tachycardia and stimulates renin.","RAAS activation retains sodium and water, so they are combined with a β-blocker and a diuretic."]],
  ["CA-448","ASSOCIATION","Cardiomyopathy & tumors","Young man faints while jogging; asymmetric septal hypertrophy — what obstructs the outflow?","Mitral leaflet and septum",["Aortic valve cusps","Papillary muscles","Chordae tendineae"],["In hypertrophic cardiomyopathy the thick septum narrows the outflow tract.","Fast flow pulls the anterior mitral leaflet toward the septum in systole (systolic anterior motion).","Leaflet and septum together obstruct the outflow."]],
  ["CA-449","ASSOCIATION","Cardiac physiology","Endurance athlete with a soft murmur at the left 2nd interspace that disappears on standing","Larger stroke volume",["Thickened pulmonic valve","Small septal defect","Stiff left ventricle"],["Endurance training enlarges the heart and increases stroke volume.","High flow across a normal pulmonic valve can cause a benign flow murmur.","Flow murmurs soften when preload falls, such as on standing."]],
  ["CA-450","MECHANISM","Ischemic heart disease","Inferior MI with HR 40, pallor and BP 70/40 — best immediate step","Atropine",["Metoprolol","Nitroglycerin","Adenosine"],["Inferior MIs often cause bradycardia from vagal activation and RCA supply to the SA and AV nodes.","Atropine blocks muscarinic receptors and speeds the heart.","If atropine fails, pacing is used."]],
  ["CA-451","ASSOCIATION","Heart failure & shock","Older man lightheaded when he adjusts a tight collar — Holter during an episode shows","Sinus pause",["Atrial fibrillation","Ventricular tachycardia","Torsades de pointes"],["Pressure on the carotid sinus triggers an exaggerated baroreflex (carotid sinus hypersensitivity).","Vagal output causes a sinus pause or AV block, often with vasodilation.","A pacemaker helps the cardioinhibitory type."]],
  ["CA-452","SIDE_EFFECT","Arrhythmias","Man on high-dose methadone faints after brief palpitations — ECG finding","QT prolongation",["PR prolongation","Delta waves","ST elevation"],["Methadone blocks the hERG potassium channel.","This prolongs repolarisation and the QT interval.","A long QT predisposes to torsades de pointes, causing palpitations and syncope."]],
  ["CA-453","ASSOCIATION","Valves & endocarditis","Mitral stenosis with a loud S1, diastolic rumble and hoarseness — cause of the hoarseness","Nerve compression",["Laryngeal edema","Vocal cord nodules","Vocal cord vasculitis"],["Mitral stenosis enlarges the left atrium.","A large left atrium (or pulmonary artery) can compress the left recurrent laryngeal nerve.","Hoarseness from this compression is Ortner syndrome."]],
  ["CA-454","ASSOCIATION","Heart failure & shock","Lightheaded when buttoning a tight collar — afferent nerve carrying the reflex","Glossopharyngeal",["Vagus","Hypoglossal","Facial"],["Carotid sinus baroreceptors send signals through the glossopharyngeal nerve (CN IX).","Aortic arch baroreceptors send signals through the vagus nerve (CN X).","The efferent limb of the reflex runs in the vagus to the heart."]],
  ["CA-455","MECHANISM","Hypertension","Hypertensive man: right kidney 7 cm, left kidney 11 cm — mechanism of the small kidney","Oxygen and nutrient deprivation",["Chronic urinary obstruction","Immune-complex deposition","Recurrent kidney infection"],["Unilateral renal artery stenosis, usually atherosclerotic in older patients, reduces blood flow.","Chronic ischemia causes atrophy of the affected kidney.","The ischemic kidney releases renin, causing renovascular hypertension."]],
  ["CA-456","ASSOCIATION","Pericardium","Lupus patient with positional chest pain, a three-part rub and diffuse ST elevation","Fibrinous pericarditis",["Purulent pericarditis","Caseous pericarditis","Hemorrhagic pericarditis"],["Lupus is a classic cause of fibrinous pericarditis.","Fibrin on the pericardial surfaces creates a friction rub.","Diffuse ST elevation with PR depression is typical of acute pericarditis."]],
  ["CA-457","ASSOCIATION","Pericardium","Days of sharp pleuritic chest pain after a URI with a moderate pericardial effusion — likely cause","Viral infection",["Bacterial infection","Tuberculosis","Malignancy"],["Viral infection (Coxsackie B and others) is the commonest cause of acute pericarditis.","Pain is sharp, pleuritic and relieved by leaning forward.","Treatment is NSAIDs plus colchicine, which reduces recurrence."]],
  ["CA-458","ASSOCIATION","Cardiomyopathy & tumors","Runner with asymmetric wall thickening, high LV mass and EF 70% — pathologic finding","Myofibril disarray",["Fatty infiltration","Amyloid deposits","Lymphocytic infiltrate"],["Hypertrophic cardiomyopathy shows hypertrophied myocytes arranged in a disorganised pattern.","Myofibril disarray and interstitial fibrosis are its hallmarks.","This differs from athlete's heart, which has uniform, organised hypertrophy."]],
  ["CA-459","ASSOCIATION","Pericardium","Dialysis patient with a tunnelled catheter and cloudy neutrophil-rich pericardial fluid — organism","Gram-positive cocci in clusters",["Gram-positive cocci in chains","Gram-negative diplococci","Acid-fast bacilli"],["Cloudy fluid full of neutrophils is purulent pericarditis.","Indwelling catheters let skin bacteria into the bloodstream.","Staphylococcus aureus, a gram-positive coccus in clusters, is the commonest cause."]],
  ["CA-460","ASSOCIATION","Congenital & fetal","Term newborn cyanotic at birth with no murmur and a narrow mediastinum — cause of the cyanosis","Parallel pulmonary and systemic circuits",["Obstructed pulmonary outflow","Mixing in a single ventricle","Pulmonary veins draining to the right atrium"],["Transposition of the great arteries causes severe cyanosis at birth.","The aorta arises from the right ventricle and the pulmonary artery from the left, creating parallel circuits.","The x-ray shows an egg-on-a-string heart with a narrow mediastinum."]],
  ["CA-461","MECHANISM","Cardiac drugs","Stable angina relieved by sublingual nitroglycerin — main hemodynamic change","Lower LV end-diastolic volume",["Lower heart rate","Higher coronary resistance","Higher LV contractility"],["Nitroglycerin mainly dilates veins, so more blood pools in them.","Less venous return lowers preload and left ventricular end-diastolic volume.","Smaller volume reduces wall stress and myocardial oxygen demand."]],
  ["CA-462","MECHANISM","Ischemic heart disease","Anterior STEMI in a patient with COPD — which β-blocker is preferred?","Metoprolol",["Propranolol","Nadolol","Labetalol"],["β-blockers reduce oxygen demand and mortality after MI.","Nonselective β-blockers block β2 receptors and can cause bronchospasm.","Cardioselective β1 blockers such as metoprolol are safer in COPD and asthma."]],
  ["CA-463","ASSOCIATION","Congenital & fetal","Toddler with a continuous machinery murmur at the left sternal border, loudest at S2","Patent ductus arteriosus",["Ventricular septal defect","Atrial septal defect","Aortic regurgitation"],["A patent ductus causes a continuous machinery murmur, loudest at S2.","It is heard best below the left clavicle.","It is associated with prematurity and congenital rubella."]],
  ["CA-464","ASSOCIATION","Vascular disease","Sudden severe chest pain, hypotension, impalpable apex and cold limbs, then death — autopsy","Blood in the pericardial space",["Rupture of a papillary muscle","Clot in the pulmonary trunk","Rupture of the septum"],["An ascending aortic dissection can rupture into the pericardium.","Hemopericardium causes acute cardiac tamponade.","Tamponade explains the hypotension, absent apex beat and rapid death."]],
  ["CA-465","ASSOCIATION","Vascular disease","Very tall young man with lens dislocation and long fingers — most likely cause of death","Aortic disease",["Pulmonary disease","Kidney disease","Brain disease"],["Marfan syndrome is a fibrillin-1 defect inherited as autosomal dominant.","It causes cystic medial degeneration of the aorta.","Aortic root dilation, regurgitation and dissection are the main causes of death."]],
  ["CA-466","MECHANISM","Cardiac drugs","Heart failure on a loop diuretic develops K⁺ 2.2 — added diuretic acts mainly on","Cortical collecting duct",["Proximal convoluted tubule","Thick ascending limb","Early distal tubule"],["Loop diuretics deliver more sodium distally, increasing potassium secretion.","Potassium-sparing diuretics (spironolactone, eplerenone, amiloride) act on the cortical collecting duct.","They block aldosterone or ENaC, reducing potassium loss; spironolactone also improves survival in HFrEF."]],
  ["CA-557","MECHANISM","Arrhythmias","Palpitations stop with gentle massage below the angle of the jaw — mechanism","Longer AV node refractory period",["Shorter AV node refractory period","Faster SA node firing","Blocked accessory pathway"],["Carotid sinus massage raises vagal tone.","Vagal tone slows AV nodal conduction and lengthens its refractory period.","This breaks AV nodal reentry and ends the supraventricular tachycardia."]],
  ["CA-558","ASSOCIATION","Vascular disease","Bowel ischemia after recent catheterisation; vessels contain needle-shaped clefts — highest risk of","Acute kidney injury",["Acute liver failure","Acute pancreatitis","Acute stroke"],["Catheter manipulation can dislodge cholesterol from atherosclerotic plaques.","Cholesterol crystals lodge in small arteries, leaving clefts on histology.","The kidneys are most often hit, causing acute kidney injury, with livedo reticularis and eosinophilia."]],
  ["CA-559","MECHANISM","Cardiac drugs","HFrEF with refractory edema; metolazone is added to furosemide — which loop effect does it exploit?","More sodium reaching the distal tubule",["Less potassium in the collecting duct","Lower renal blood flow","More renin secretion"],["Loop diuretics block sodium reabsorption in the thick ascending limb.","More sodium reaches the distal tubule, which adapts by reabsorbing more.","A thiazide-like drug such as metolazone blocks this distal reabsorption (sequential nephron blockade)."]],
  ["CA-560","ASSOCIATION","Anatomy","After femoral catheterisation he becomes cold, clammy and hypotensive with only a small groin bruise","Retroperitoneal space",["Femoral sheath","Rectus sheath","Peritoneal cavity"],["Puncturing the femoral artery above the inguinal ligament risks bleeding that cannot be compressed.","Blood tracks into the retroperitoneum, which can hold litres with little visible bruising.","Hypotension and back or flank pain after a femoral procedure suggest retroperitoneal hemorrhage."]],
  ["CA-561","ASSOCIATION","Cardiac physiology","Healthy woman runs to 90% of maximum heart rate — blood pressure changes","Systolic up, diastolic same, pulse pressure up",["Systolic up, diastolic up, pulse pressure same","Systolic same, diastolic down, pulse pressure up","Systolic down, diastolic down, pulse pressure down"],["Stroke volume and contractility rise with exercise, raising systolic pressure.","Vasodilation in working muscle lowers resistance, so diastolic pressure stays about the same.","The result is a wider pulse pressure."]],
  ["CA-562","SIDE_EFFECT","Cardiac drugs","Older man on a drug for his prostate falls when getting out of bed; BP drops on standing","α1 adrenergic",["β1 adrenergic","Muscarinic M2","α2 adrenergic"],["α1 blockers (terazosin, doxazosin) relax prostate smooth muscle in BPH.","They also dilate vessels and blunt the reflex vasoconstriction needed on standing.","First-dose orthostatic hypotension is common, so they are started at bedtime."]],
  ["CA-563","ASSOCIATION","Ischemic heart disease","Prolonged chest pain — electron microscopy sign of irreversible myocyte injury","Mitochondrial vacuolisation",["Ribosome detachment","Cellular swelling","Membrane blebbing"],["Reversible injury shows cell swelling, membrane blebs and ribosome detachment.","Irreversible injury shows mitochondrial vacuoles, amorphous densities and membrane rupture.","Calcium flooding into mitochondria marks the point of no return."]],
  ["CA-564","MECHANISM","Ischemic heart disease","Brief myocardial ischemia makes myocytes swell — partly because of","Intracellular calcium buildup",["Intracellular potassium buildup","Extracellular sodium buildup","Intracellular ATP buildup"],["Ischemia stops oxidative phosphorylation, so ATP falls.","The Na⁺/K⁺-ATPase fails, and sodium and calcium build up inside the cell.","The extra solute draws water in, causing swelling."]],
  ["CA-565","ASSOCIATION","Vascular disease","Hypertensive woman with tearing chest pain to the back, wide mediastinum and pulsus paradoxus faints","Pericardial fluid accumulation",["Vasovagal reflex","Complete heart block","Pulmonary embolism"],["A type A aortic dissection can rupture back into the pericardium.","Blood in the pericardial sac causes tamponade.","Pulsus paradoxus and hypotension reflect the restricted filling."]],
  ["CA-566","MECHANISM","Ischemic heart disease","Smoker with nocturnal chest pressure; acetylcholine reproduces pain without stenosis — explanation","Endothelial dysfunction",["Fixed atherosclerotic plaque","Coronary artery embolism","Coronary artery dissection"],["Normally, acetylcholine releases nitric oxide from the endothelium, causing dilation.","When the endothelium is dysfunctional, acetylcholine acts directly on smooth muscle and causes constriction.","This underlies vasospastic angina, which smoking worsens."]],
  ["CA-567","ASSOCIATION","Heart failure & shock","Alveolar macrophages hold golden-brown granules that stain blue with Prussian blue","Left ventricular dysfunction",["Pulmonary hypertension","Coal dust inhalation","Iron overload"],["The granules are hemosiderin.","Left heart failure raises pulmonary venous pressure, so red cells leak into the alveoli.","Macrophages that eat the red cells become heart failure cells."]],
  ["CA-568","MECHANISM","Cardiomyopathy & tumors","Woman dies after exertional chest pressure and palpitations; myocytes show disarray — cause","Sarcomere protein mutation",["Desmosome protein mutation","Dystrophin gene deletion","Transthyretin gene mutation"],["Hypertrophic cardiomyopathy shows hypertrophied myocytes in disarray with fibrosis.","It is usually caused by mutations in sarcomere genes such as β-myosin heavy chain.","It causes angina, syncope and sudden death from arrhythmia."]],
  ["CA-569","ASSOCIATION","Cardiomyopathy & tumors","Young man dies in his sleep; thin LV apex, no coronary disease and a dilated esophagus — key history","Where he has lived",["Recent travel by air","Family history of disease","Alcohol use"],["An apical aneurysm with megaesophagus points to chronic Chagas disease.","Trypanosoma cruzi is spread by the reduviid (kissing) bug in Latin America.","It causes dilated cardiomyopathy, apical aneurysm, conduction disease and megacolon."]],
  ["CA-570","ASSOCIATION","Arrhythmias","ECG shows sawtooth atrial flutter waves — where should ablation create a block?","Between tricuspid valve and IVC",["Around the pulmonary veins","Across the AV node","Across the left atrial roof"],["Typical atrial flutter is a macroreentrant circuit around the tricuspid annulus in the right atrium.","The cavotricuspid isthmus is a narrow, essential part of that circuit.","Ablating it cures typical flutter in most patients."]],
  ["CA-571","ASSOCIATION","Heart failure & shock","Young woman with exertional breathlessness; echo shows an enlarged coronary sinus","Pulmonary hypertension",["Left atrial enlargement","Aortic stenosis","Mitral regurgitation"],["The coronary sinus drains into the right atrium.","Raised right atrial pressure, as in pulmonary hypertension, dilates it.","A persistent left SVC is another cause."]],
  ["CA-572","ASSOCIATION","Valves & endocarditis","After endocarditis: bounding pulses and a to-and-fro femoral bruit — catheter pressures","Aorta 160/60, LV 160/20",["Aorta 120/80, LV 160/10","Aorta 160/60, LV 160/5","Aorta 100/70, LV 100/25"],["Aortic regurgitation lets blood fall back from the aorta into the ventricle.","Aortic diastolic pressure falls, while LV diastolic pressure rises from the extra volume.","Large stroke volumes raise systolic pressure in both; Duroziez sign is the femoral bruit."]],
  ["CA-573","ASSOCIATION","Heart failure & shock","Sudden dyspnea and chest pain with respiratory alkalosis and hypoxemia — bedside echo","Enlarged right ventricular cavity",["Enlarged left ventricular cavity","Large pericardial effusion","Thickened mitral leaflets"],["A massive pulmonary embolism suddenly raises pulmonary resistance.","The thin right ventricle dilates acutely under the pressure load.","Echo may show RV dilation, septal flattening and McConnell sign."]],
  ["CA-574","ASSOCIATION","Anatomy","Ablation catheter from the femoral vein must reach the left atrium — it passes through","Interatrial septum",["Tricuspid valve","Coronary sinus","Pulmonary trunk"],["A venous catheter reaches the right atrium first.","To reach the left atrium it crosses the interatrial septum (transseptal puncture).","The puncture is made at the thin fossa ovalis."]],
  ["CA-575","MECHANISM","Congenital & fetal","Teen girl with an early systolic murmur at the LUSB and a widely fixed split S2 — mechanism","More blood flow to the lungs",["Narrowed pulmonic valve","Flow across a septal defect","Regurgitant tricuspid valve"],["An atrial septal defect shunts blood left to right at the atria.","The extra volume crosses a normal pulmonic valve, causing a flow murmur.","Flow across the ASD itself is low pressure and silent."]],
  ["CA-576","MECHANISM","Vascular disease","Femoral clot removed; creatine kinase then rises rapidly — why?","Cell membrane damage",["Mitochondrial swelling","Cell lysis from infection","Decreased renal clearance"],["Restoring flow to ischemic muscle causes reperfusion injury.","Free radicals and calcium overload damage cell membranes.","Creatine kinase leaks out, and potassium and myoglobin can follow."]],
  ["CA-577","MECHANISM","Hypertension","Addison disease treated with fludrocortisone — expected effects","Vascular sensitivity up, volume up, urine Na⁺ down",["Vascular sensitivity down, volume up, urine Na⁺ up","Vascular sensitivity up, volume down, urine Na⁺ up","Vascular sensitivity down, volume down, urine Na⁺ down"],["Fludrocortisone is a synthetic mineralocorticoid.","It increases sodium reabsorption, so urine sodium falls and blood volume rises.","It also increases vascular sensitivity to vasoconstrictors, improving standing blood pressure."]],
  ["CA-578","ASSOCIATION","Valves & endocarditis","Mitral stenosis with a loud S1 and a mid-diastolic rumble — LV findings at rest","Pressure, afterload and contractility normal",["Pressure high, afterload and contractility normal","Pressure normal, afterload high, contractility low","Pressure high, afterload high, contractility high"],["In mitral stenosis the obstruction is upstream of the left ventricle.","The left ventricle is protected and fills less, so its diastolic pressure is normal or low.","Its afterload and contractility stay normal, while left atrial pressure rises."]],
  ["CA-579","MECHANISM","Cardiac drugs","Low-dose atenolol — direct effect on cAMP in different cells","Heart ↓, JG cells ↓, vessels same",["Heart ↓, JG cells same, vessels ↓","Heart same, JG cells ↓, vessels ↓","Heart ↓, JG cells ↓, vessels ↓"],["Atenolol is a selective β1 blocker at low doses.","β1 receptors on myocytes and juxtaglomerular cells act through Gs and cAMP.","Vascular smooth muscle relaxes via β2 receptors, which atenolol spares."]],
  ["CA-580","ASSOCIATION","Valves & endocarditis","Dyspnea and orthopnea; left atrial tracing shows a large, early v wave","Mitral regurgitation",["Mitral stenosis","Aortic stenosis","Aortic regurgitation"],["In mitral regurgitation, blood leaks into the left atrium during systole.","That surge produces a giant v wave in the left atrial or wedge tracing.","Chronic MR dilates the left atrium and ventricle."]],
  ["CA-581","MECHANISM","Vascular disease","Young woman with weak left radial pulse, unequal arm BPs, bruits and ESR 110","Granulomatous large-artery inflammation",["Necrotising medium-artery inflammation","Immune-complex small-vessel inflammation","Fibromuscular dysplasia of arteries"],["Takayasu arteritis affects the aortic arch and its branches.","It mainly affects young Asian women and causes \"pulseless disease\".","Histology shows granulomatous inflammation; treatment is glucocorticoids."]],
  ["CA-582","ASSOCIATION","Ischemic heart disease","MI complicated by new Mobitz I (Wenckebach) block — which artery?","Right coronary",["Left anterior descending","Left circumflex","Left main"],["The AV nodal artery comes from the right coronary artery in about 90% of people.","Inferior MI from RCA occlusion often causes AV nodal block.","Mobitz I in inferior MI is usually transient and benign."]],
  ["CA-583","MECHANISM","Cardiac physiology","Severe chronic coronary stenosis but normal EF and no wall motion defect — plaque feature","Slow growth",["Thin fibrous cap","Large lipid core","Superficial erosion"],["A plaque that grows slowly gives time for collateral vessels to develop.","Collaterals keep the muscle beyond the stenosis alive.","Rapid occlusion of an unstable plaque leaves no time for collaterals, so infarction follows."]],
  ["CA-584","MECHANISM","Hypertension","New drug causes natriuresis and a sustained fall in both angiotensin II and aldosterone","Direct renin inhibitor",["ACE inhibitor","Angiotensin receptor blocker","Aldosterone antagonist"],["Aliskiren blocks renin, the first step of the RAAS.","Angiotensin I and II and aldosterone all fall, even as renin levels rise.","ACE inhibitors allow angiotensin II escape, and ARBs raise angiotensin II."]],
  ["CA-585","ASSOCIATION","Arrhythmias","Forestry worker in the northeast US with a recent rash, now has complete heart block","Disseminated spirochetal infection",["Viral myocarditis","Cardiac sarcoidosis","Degenerative conduction disease"],["Lyme disease is caused by Borrelia burgdorferi, a spirochete spread by Ixodes ticks.","Early disseminated Lyme can cause carditis with AV block of any degree.","It is usually reversible with antibiotics such as ceftriaxone."]],
  ["CA-586","ASSOCIATION","Cardiac physiology","Volunteer's heart rate and cardiac output rise while arterial O₂ and CO₂ stay normal","Exercise",["Hemorrhage","Hypoxemia","Sepsis"],["Exercise raises heart rate, stroke volume and cardiac output.","Ventilation increases in step with metabolism, keeping arterial gases normal.","Hemorrhage, hypoxemia and sepsis cause abnormal gas or pressure values."]],
  ["CA-587","ASSOCIATION","Valves & endocarditis","Healthy man, sudden dyspnea; flail mitral leaflet from chordal rupture — LV hemodynamics","Afterload ↓, preload ↑, EF ↑",["Afterload ↑, preload ↓, EF ↓","Afterload ↓, preload ↓, EF ↓","Afterload ↑, preload ↑, EF ↑"],["In acute mitral regurgitation, blood exits into the low-pressure left atrium.","Afterload falls and ejection fraction rises, but forward stroke volume falls.","Regurgitant volume returns to the ventricle, raising preload; the small atrium causes pulmonary edema."]],
  ["CA-588","SIDE_EFFECT","Cardiac drugs","Elderly man with nausea, confusion and yellow-tinted vision — age-related change responsible","Renal clearance",["Hepatic metabolism","Plasma protein binding","Gastric acid secretion"],["Digoxin is cleared mainly by the kidneys.","Glomerular filtration falls with age, so digoxin accumulates.","Toxicity causes GI upset, confusion, visual changes and arrhythmias."]],
  ["CA-589","ASSOCIATION","Pericardium","After a URI: hypotension, tachycardia, distended neck veins, clear lungs and a pulse lost on inspiration","Cardiac tamponade",["Constrictive pericarditis","Tension pneumothorax","Right ventricular infarction"],["Beck triad is hypotension, distended neck veins and muffled heart sounds.","Pulsus paradoxus — a fall of more than 10 mm Hg on inspiration — is typical.","Viral pericarditis with a large effusion can cause tamponade; treat with pericardiocentesis."]],
  ["CA-590","MECHANISM","Valves & endocarditis","Angina with slow-rising carotids, a 50 mm Hg aortic gradient and only a 30% LAD lesion","Higher LV wall stress",["Lower LV preload","Coronary vasospasm","Lower LV mass"],["Aortic stenosis raises the pressure the ventricle must generate.","Higher wall stress and greater muscle mass increase oxygen demand.","Subendocardial perfusion falls, causing angina even with near-normal coronaries."]],
  ["CA-591","ASSOCIATION","Ischemic heart disease","Ruptured left main plaque — which cell builds the fibrous part of a plaque?","Smooth muscle cells",["Macrophages","Endothelial cells","T lymphocytes"],["Growth factors such as PDGF draw smooth muscle cells from the media into the intima.","These cells make collagen and matrix that form the fibrous cap.","Macrophage enzymes later weaken the cap, leading to rupture."]],
  ["CA-592","ASSOCIATION","Congenital & fetal","Infant with tetralogy of Fallot has no cyanosis or spells — what decides severity?","Degree of RV outflow obstruction",["Size of the septal defect","Degree of aortic override","Thickness of the RV wall"],["In tetralogy, the VSD is large, so pressures equalise between the ventricles.","The degree of right ventricular outflow obstruction decides how much blood shunts right to left.","Mild obstruction gives a \"pink tet\" with little or no cyanosis."]],
  ["CA-593","SIDE_EFFECT","Cardiomyopathy & tumors","Young man with exertional chest pain; murmur much louder on standing — which drug to avoid?","Isosorbide dinitrate",["Metoprolol","Verapamil","Disopyramide"],["A murmur that gets louder on standing suggests hypertrophic cardiomyopathy.","Nitrates lower preload, shrinking the ventricle and worsening outflow obstruction.","Diuretics, vasodilators and digoxin also worsen HCM obstruction."]],
  ["CA-594","ASSOCIATION","Hypertension","Right renal artery 95% stenosed, left normal — compared with the right, the left kidney shows","Thickened arteriolar walls",["Smaller kidney size","Tubular atrophy","Lower renin content"],["The stenosed right kidney is protected from high pressure but becomes atrophic.","The left kidney is exposed to the renin-driven systemic hypertension.","It develops hypertensive nephrosclerosis with hyaline arteriolosclerosis."]],
  ["CA-595","ASSOCIATION","Ischemic heart disease","Perfusion scan shows inducible ischemia of the inferior wall — which artery?","Right coronary",["Left anterior descending","Left circumflex","Left main"],["The inferior wall is supplied by the posterior descending artery.","In most people (right dominance) the PDA comes from the right coronary artery.","Inferior ischemia shows on ECG leads II, III and aVF."]],
  ["CA-596","ASSOCIATION","Valves & endocarditis","Older hypertensive man with a crescendo–decrescendo systolic murmur at the base — cause","Valve calcification",["Rheumatic scarring","Myxomatous degeneration","Congenital valve fusion"],["A crescendo-decrescendo murmur at the base is aortic stenosis.","After age 70, the commonest cause is degenerative calcific disease of a tricuspid valve.","Risk factors resemble those of atherosclerosis."]],
  ["CA-597","ASSOCIATION","Cardiac physiology","Swan-Ganz balloon occludes a pulmonary artery branch — the reading reflects","Left atrial pressure",["Pulmonary artery pressure","Right atrial pressure","Right ventricular pressure"],["With the branch occluded, a static column of blood connects the catheter tip to the left atrium.","The pulmonary capillary wedge pressure approximates left atrial pressure.","It also approximates LV end-diastolic pressure unless mitral stenosis is present."]],
  ["CA-598","MECHANISM","Cardiac drugs","Hypertension with HR 55 and PR 280 ms — drug that lowers BP without worsening the ECG","Nifedipine",["Verapamil","Diltiazem","Metoprolol"],["Dihydropyridines act mainly on vascular smooth muscle.","They have little effect on SA and AV nodal conduction.","Verapamil, diltiazem and β-blockers would worsen the bradycardia and AV block."]],
  ["CA-599","ASSOCIATION","Arrhythmias","Paroxysmal palpitations; strip is irregularly irregular with no P waves — trigger site","Pulmonary veins",["Sinoatrial node","Atrioventricular node","Coronary sinus"],["Atrial fibrillation is usually triggered by ectopic beats from the pulmonary vein sleeves.","Myocardial sleeves extend into the veins where they join the left atrium.","Catheter ablation isolates the pulmonary veins electrically."]],
  ["CA-600","MECHANISM","Cardiac drugs","Hypertensive heart failure relieved by high-dose IV nitroglycerin — hemodynamic changes","LVEDP ↓, venous capacitance ↑, SVR ↓",["LVEDP ↑, venous capacitance ↓, SVR ↑","LVEDP ↓, venous capacitance ↓, SVR ↑","LVEDP ↑, venous capacitance ↑, SVR ↓"],["Nitroglycerin dilates veins, increasing venous capacitance and lowering preload.","Lower preload reduces LV end-diastolic pressure and pulmonary congestion.","At high doses it also dilates arterioles, lowering systemic vascular resistance."]],
  ["CA-601","MECHANISM","Vascular disease","Leg swelling with thick dry skin after groin node dissection for melanoma — treatment","Compression to increase lymph flow",["Diuretics to remove fluid","Anticoagulation for a clot","Antibiotics for infection"],["Removal of inguinal lymph nodes causes chronic lymphedema.","Protein-rich fluid collects, and the skin thickens and becomes fibrotic.","Compression, elevation and manual lymphatic drainage are the mainstays."]],
  ["CA-602","SIDE_EFFECT","Cardiac drugs","Septic shock on a norepinephrine drip; the vein turns white and the tissue cold and pale","Phentolamine",["Hyaluronidase","Propranolol","Hydralazine"],["Extravasated norepinephrine causes intense local α1 vasoconstriction and tissue ischemia.","Phentolamine, a reversible α blocker, is injected locally.","It reverses the vasoconstriction and limits necrosis."]],
  ["CA-603","ASSOCIATION","Valves & endocarditis","Catheter tracings show a large LV-to-aorta systolic gradient — when is the murmur loudest?","Mid systole",["Early diastole","Late diastole","Throughout systole"],["A pressure gradient across the aortic valve in systole is aortic stenosis.","The gradient and the murmur peak in mid systole.","As stenosis worsens, the peak moves later (late-peaking murmur)."]],
  ["CA-604","ASSOCIATION","Cardiomyopathy & tumors","Young woman with fever, weight loss and a pedunculated left atrial mass — histology","Scattered cells in a mucoid stroma",["Spindle cells in a palisade","Fibrin with neutrophils","Laminated thrombus"],["A pedunculated left atrial mass is a myxoma.","Histology shows stellate cells in an abundant mucopolysaccharide stroma.","Myxomas can cause constitutional symptoms through IL-6 and a tumor plop in diastole."]],
  ["CA-605","ASSOCIATION","Valves & endocarditis","Cambodian immigrant with childhood knee swelling; apical blowing holosystolic murmur","Mitral regurgitation",["Mitral stenosis","Aortic stenosis","Tricuspid regurgitation"],["A blowing holosystolic murmur at the apex radiating to the axilla is mitral regurgitation.","Childhood migratory arthritis suggests acute rheumatic fever.","Acute rheumatic carditis typically causes mitral regurgitation; stenosis comes later."]],
  ["CA-606","ASSOCIATION","Cardiac physiology","At rest, the largest O₂ content difference from the aorta is in which vein?","Coronary sinus",["Renal vein","Hepatic vein","Jugular vein"],["The heart extracts about 70 to 80% of delivered oxygen even at rest.","Coronary sinus blood is therefore the most deoxygenated in the body.","The heart meets extra demand mainly by increasing flow, not extraction."]],
  ["CA-607","MECHANISM","Congenital & fetal","Premature baby with a continuous murmur and bounding pulses — drug mechanism to fix the cause","Cyclooxygenase inhibition",["Phosphodiesterase inhibition","Prostaglandin E1 stimulation","β-receptor blockade"],["Prostaglandin E2 keeps the ductus arteriosus open.","Indomethacin or ibuprofen inhibits COX, lowering PGE2.","This closes the patent ductus; acetaminophen is an alternative."]],
  ["CA-608","ASSOCIATION","Pericardium","Heart failure after chest radiation; autopsy shows dense fibrous tissue filling the pericardial space","Kussmaul sign",["Pulsus alternans","Opening snap","Water-hammer pulse"],["Fibrous thickening of the pericardium is constrictive pericarditis.","On inspiration, venous return rises but the rigid pericardium cannot expand.","The jugular venous pressure rises paradoxically on inspiration (Kussmaul sign)."]],
  ["CA-609","MECHANISM","Congenital & fetal","Boy with tetralogy of Fallot squats during cyanotic spells — how does it help?","Raising systemic vascular resistance",["Lowering systemic vascular resistance","Lowering venous return","Raising heart rate"],["Squatting kinks the femoral arteries, raising systemic resistance.","Higher left-sided pressure reduces right-to-left flow across the VSD.","More right ventricular blood goes to the lungs, improving oxygenation."]],
  ["CA-610","MECHANISM","Cardiac drugs","New drug slows phase 0 and lengthens phase 3 of the ventricular action potential","Disopyramide",["Lidocaine","Flecainide","Sotalol"],["Class IA drugs block sodium channels moderately and potassium channels too.","They slow phase 0, widen the QRS and lengthen the QT.","Class IA includes quinidine, procainamide and disopyramide."]],
  ["CA-611","ASSOCIATION","Vascular disease","Acalculous cholecystitis with renal involvement; submucosal arteries show fibrinoid necrosis","Polyarteritis nodosa",["Granulomatosis with polyangiitis","Giant cell arteritis","Takayasu arteritis"],["Polyarteritis nodosa is a necrotising vasculitis of medium-sized arteries.","It affects the kidneys, gut, skin and nerves but spares the lungs.","It is associated with hepatitis B and is ANCA negative."]],
  ["CA-612","ASSOCIATION","Ischemic heart disease","Three days after a transmural STEMI, sharp pleuritic chest pain — cause","Pericardium over the infarct is inflamed",["Reinfarction in the same artery","Rupture of a papillary muscle","Autoimmune serositis weeks later"],["Peri-infarction pericarditis appears 1 to 3 days after a transmural MI.","Inflammation of the pericardium over the necrotic wall causes pleuritic pain and a rub.","Dressler syndrome is autoimmune and appears weeks later."]],
  ["CA-613","ASSOCIATION","Vascular disease","Tall slim man with pectus excavatum and a new AR murmur dies after lifting — aortic histology","Fragmented elastic lamellae",["Granulomas in the adventitia","Plaque with a thin fibrous cap","Calcified media in small arteries"],["Marfan syndrome weakens the aortic media through fibrillin-1 deficiency.","Elastic lamellae fragment, leaving cystic medial degeneration.","Aortic root dissection can cause acute aortic regurgitation and death."]],
  ["CA-614","ASSOCIATION","Valves & endocarditis","Middle-aged man lightheaded on walks; harsh crescendo–decrescendo murmur at the right sternal border","Bicuspid aortic valve",["Rheumatic heart disease","Hypertrophic cardiomyopathy","Infective endocarditis"],["A harsh systolic ejection murmur at the right upper sternal border is aortic stenosis.","Under about 70, the commonest cause is a congenital bicuspid valve.","Bicuspid valves calcify earlier than normal tricuspid valves."]],
  ["CA-615","ASSOCIATION","Congenital & fetal","Stroke after a leg DVT; bubble study is negative at rest — maneuver to reveal a shunt","Valsalva release",["Valsalva strain","Leg raise","Handgrip"],["During Valsalva strain, venous return falls.","On release, a surge of blood returns to the right atrium, transiently raising its pressure.","Right atrial pressure then exceeds left, opening a PFO so bubbles cross."]],
  ["CA-616","SIDE_EFFECT","Hypertension","Woman with hypertension, diabetes and a recent MI has a persistent dry cough — next step","Careful review of current medications",["Chest CT scan","Pulmonary function tests","Empirical antibiotics"],["After an MI, especially with diabetes, patients are usually on an ACE inhibitor.","ACE inhibitors cause cough by preventing bradykinin breakdown.","Switching to an ARB stops the cough."]],
  ["CA-617","ASSOCIATION","Heart failure & shock","Toddler with days of diarrhea, now lethargic with sunken eyes — expected change","Faster breathing",["Slower heart rate","Warm, flushed skin","Higher urine output"],["Severe volume loss causes hypovolemic shock.","Poor tissue perfusion produces lactic acidosis.","Breathing quickens to blow off CO₂ and compensate."]],
  ["CA-618","ASSOCIATION","Cardiac physiology","Blood flow curve that falls sharply in systole and recovers in diastole — which tissue?","Left ventricular myocardium",["Right ventricular myocardium","Skeletal muscle at rest","Renal cortex"],["During systole, the contracting left ventricle compresses its own vessels.","Flow drops or even reverses in systole and is restored in diastole.","The right ventricle generates lower pressure, so its flow continues during systole."]],
  ["CA-619","ASSOCIATION","Arrhythmias","Elderly man near-faints; strip shows P waves and QRS complexes on separate rhythms","Degeneration of the AV node",["Accessory pathway conduction","Sinus node reentry","Atrial flutter with block"],["Third-degree AV block shows complete dissociation of P waves and QRS complexes.","In older adults, fibrosis and degeneration of the conducting system is the commonest cause.","Symptomatic complete heart block needs a permanent pacemaker."]],
  ["CA-620","ASSOCIATION","Heart failure & shock","Doxorubicin-treated woman with crackles and leg edema — RA pressure and LVEDP","Both raised",["Both normal","RA raised, LVEDP normal","RA normal, LVEDP raised"],["Doxorubicin causes a dilated cardiomyopathy with systolic failure.","Left ventricular failure raises LVEDP and causes pulmonary congestion.","Back-pressure eventually raises right atrial pressure, causing peripheral edema."]],
  ["CA-621","MECHANISM","Valves & endocarditis","Decompensated heart failure with mitral regurgitation — what boosts forward relative to regurgitant flow?","Lower systemic vascular resistance",["Higher systemic vascular resistance","Higher heart rate","Higher preload"],["In mitral regurgitation, blood can leave forward into the aorta or backward into the atrium.","Lower afterload makes forward ejection easier.","Afterload reducers (nitroprusside, ACE inhibitors) increase forward stroke volume."]],
  ["CA-622","ASSOCIATION","Heart failure & shock","Exertional dyspnea after a kidney transplant from a still-open dialysis fistula — changes","Output up, SVR down, venous return up",["Output down, SVR up, venous return down","Output up, SVR up, venous return down","Output down, SVR down, venous return up"],["An AV fistula shunts blood from artery to vein, bypassing resistance vessels.","Systemic resistance falls and venous return rises.","Cardiac output rises to compensate, which can cause high-output heart failure."]],
  ["CA-623","MECHANISM","Cardiac drugs","Ventricular arrhythmia after STEMI treated with a drug that acts on ischemic fibres, sparing normal ones","Lidocaine",["Procainamide","Flecainide","Amiodarone"],["Class IB drugs bind sodium channels in their inactivated state.","Ischemic, depolarised tissue has many inactivated channels, so it is targeted.","Rapid unbinding means little effect on normal tissue at normal rates."]],
  ["CA-624","MECHANISM","Valves & endocarditis","Chronic severe aortic regurgitation after endocarditis — what maintains cardiac output?","Larger LV stroke volume",["Faster heart rate","Higher systemic resistance","Stronger atrial kick"],["Chronic volume overload causes eccentric hypertrophy.","The dilated ventricle ejects a much larger total stroke volume.","This large stroke volume offsets the regurgitant fraction and maintains forward output."]],
  ["CA-625","SIDE_EFFECT","Cardiac drugs","Severe hypertriglyceridemia; new drug causes flushing and warmth — mediator","Prostaglandin",["Histamine","Bradykinin","Serotonin"],["Niacin lowers triglycerides and raises HDL.","It causes flushing by stimulating prostaglandin release in the skin.","Taking aspirin beforehand reduces the flushing."]],
  ["CA-626","ASSOCIATION","Ischemic heart disease","MI with acute severe MR from a ruptured posteromedial papillary muscle — which artery?","Posterior descending",["Left anterior descending","Left circumflex","Left marginal"],["The posteromedial papillary muscle has a single blood supply from the PDA.","The anterolateral muscle has a dual supply (LAD and circumflex) and rarely ruptures.","Papillary muscle rupture occurs 2 to 7 days after MI."]],
  ["CA-627","ASSOCIATION","Pericardium","Young man after a respiratory illness, with sharp chest pain eased by leaning forward — exam finding","Friction rub",["Opening snap","Third heart sound","Pulsus alternans"],["Acute pericarditis causes sharp pleuritic chest pain eased by sitting forward.","A scratchy pericardial friction rub is the classic exam finding.","ECG shows diffuse ST elevation with PR depression."]],
  ["CA-628","ASSOCIATION","Congenital & fetal","Child with a harsh holosystolic murmur at the LLSB — saturation pattern RA, RV, LA, LV, systemic","Normal, up, normal, normal, normal",["Normal, normal, up, normal, normal","Up, up, normal, normal, normal","Normal, up, normal, down, down"],["A ventricular septal defect shunts oxygenated blood from left to right ventricle.","This raises right ventricular oxygen saturation.","Left-sided and systemic saturations stay normal because there is no right-to-left flow."]],
  ["CA-629","ASSOCIATION","Cardiac drugs","Chest tightness with tachycardia relieved by esmolol — ECG part most affected","PR interval",["QRS duration","QT interval","ST segment"],["β-blockers slow conduction through the AV node.","This lengthens the PR interval.","They have little effect on QRS width because ventricular conduction is unchanged."]],
  ["CA-630","ASSOCIATION","Arrhythmias","Young man with a regular narrow-complex tachycardia at 160 and no visible P waves — cause","Reentry inside the AV node",["Ectopic atrial focus","Accessory pathway","Sinus node reentry"],["AV nodal reentrant tachycardia is the commonest paroxysmal SVT.","Dual pathways (fast and slow) in the AV node form a reentry circuit.","Vagal maneuvers or adenosine end it; ablation of the slow pathway cures it."]],
  ["CA-631","ASSOCIATION","Valves & endocarditis","Weeks of malaise after a tooth extraction, then a stroke; friable vegetations on the atrial side of a valve","Mitral valve prolapse with regurgitation",["Normal valve with no regurgitation","Calcific aortic stenosis","Bicuspid aortic valve"],["Viridans streptococci from the mouth cause subacute endocarditis on abnormal valves.","Mitral valve prolapse with regurgitation is a common predisposing lesion in developed countries.","Friable vegetations can embolise to the brain and cause stroke."]],
  ["CA-632","MECHANISM","Cardiac physiology","Some drugs divert blood away from ischemic myocardium — which effect causes it?","Coronary arteriolar dilation",["Coronary venous dilation","Epicardial artery constriction","Lower heart rate"],["Arterioles beyond a stenosis are already maximally dilated.","A drug that dilates all coronary arterioles increases flow only to healthy regions.","Blood is stolen from the ischemic zone (coronary steal), as with dipyridamole or adenosine."]],
  ["CA-633","ASSOCIATION","Cardiomyopathy & tumors","Young man with a stroke; a mobile 3-cm left atrial mass blocks the mitral orifice — microscopy","Amorphous extracellular matrix",["Spindle cells in a palisade","Laminated fibrin and platelets","Sheets of atypical lymphocytes"],["A mobile left atrial mass that obstructs the mitral valve is a myxoma.","Fragments can embolise and cause strokes.","Histology shows scattered stellate cells in an amorphous myxoid matrix."]],
  ["CA-634","ASSOCIATION","Ischemic heart disease","Man with diabetes, hypertension and high LDL — vascular bed with the heaviest atherosclerosis","Coronary arteries",["Renal arteries","Carotid arteries","Femoral arteries"],["Atherosclerosis favours large and medium arteries at branch points.","The abdominal aorta and coronary arteries carry the heaviest burden.","Next come the popliteal arteries, internal carotids and the circle of Willis."]],
  ["CA-635","ASSOCIATION","Cardiac physiology","Shock with an isolated right ventricular infarct and the whole LV spared — artery and dominance","Right coronary, left dominant",["Right coronary, right dominant","Left circumflex, left dominant","Left anterior descending, right dominant"],["In right dominance, the RCA also supplies the inferior LV wall via the PDA.","In left dominance, the circumflex gives the PDA, so the RCA supplies only the right ventricle.","An RCA occlusion then infarcts the right ventricle alone."]],
  ["CA-636","ASSOCIATION","Pericardium","After a viral illness: pericardial effusion with late diastolic RA collapse — pulse finding","Pulse falls with inspiration",["Pulse alternates beat to beat","Pulse rises slowly and late","Pulse is bounding and collapsing"],["Right atrial collapse in diastole shows tamponade physiology.","Inspiration fills the right heart, pushing the septum left and reducing LV filling.","Systolic pressure falls more than 10 mm Hg on inspiration (pulsus paradoxus)."]],
  ["CA-637","ASSOCIATION","Valves & endocarditis","Young man with an early systolic ejection click and a soft murmur to the neck — when does that valve open?","End of isovolumic contraction",["End of isovolumic relaxation","Start of isovolumic contraction","Start of rapid filling"],["An ejection click with a soft systolic murmur in a young man suggests a bicuspid aortic valve.","The aortic valve opens when LV pressure exceeds aortic pressure.","That moment ends isovolumic contraction and starts ejection."]],
  ["CA-638","MECHANISM","Cardiac drugs","HFrEF after an MI with an S3, normal creatinine and potassium — drug that reduces mortality","Lisinopril",["Furosemide","Digoxin","Amlodipine"],["ACE inhibitors reduce mortality in HFrEF.","They lower afterload and preload and limit harmful remodelling.","Loop diuretics and digoxin relieve symptoms but do not improve survival."]],
  ["CA-639","MECHANISM","Cardiac drugs","Cramps four weeks after starting hydrochlorothiazide; triamterene is added — mechanism","Blocks epithelial sodium channels",["Blocks mineralocorticoid receptors","Blocks the Na⁺/Cl⁻ cotransporter","Blocks the Na⁺/K⁺/2Cl⁻ cotransporter"],["Thiazides deliver more sodium to the collecting duct, increasing potassium loss.","Triamterene and amiloride block ENaC in principal cells.","Less sodium uptake means less potassium secretion, correcting hypokalemia."]],
  ["CA-640","ASSOCIATION","Valves & endocarditis","Stroke and seizure; small sterile platelet-rich clots on the mitral leaflet edges","Advanced cancer",["Rheumatic fever","Injection drug use","Viridans streptococci"],["Sterile vegetations along the closure line are nonbacterial thrombotic (marantic) endocarditis.","They occur in hypercoagulable states, especially advanced cancer such as mucinous adenocarcinoma.","The vegetations embolise easily, causing strokes."]],
  ["CA-641","MECHANISM","Valves & endocarditis","Endocarditis abscess forms a fistula from the aortic root to the right ventricle — Doppler flow","Aortic root to RV, continuous",["RV to aortic root, continuous","Aortic root to RV, systole only","Aortic root to RV, diastole only"],["Aortic pressure exceeds right ventricular pressure throughout the cardiac cycle.","Blood therefore flows continuously from the aorta into the right ventricle.","This produces a continuous murmur and volume overload."]],
  ["CA-642","MECHANISM","Cardiac drugs","Septic shock refractory to fluids; norepinephrine is started — direct cellular effect","More cAMP in cardiac myocytes",["Less cAMP in cardiac myocytes","Less IP₃ in vascular smooth muscle","More cGMP in vascular smooth muscle"],["Norepinephrine stimulates α1 receptors and β1 receptors.","β1 receptors on myocytes act through Gs to raise cAMP.","α1 stimulation raises IP₃ in vascular smooth muscle, causing vasoconstriction."]],
  ["CA-643","MECHANISM","Hypertension","Severe hypertension lowered fast to 145/95; creatinine then rises with granular casts — why?","Renal autoregulation curve shifted right",["Direct hydralazine nephrotoxicity","Immune-complex glomerulonephritis","Contrast-induced nephropathy"],["Chronic hypertension shifts the kidney's autoregulatory range to higher pressures.","A rapid fall to normal pressure drops renal blood flow below the adapted range.","Ischemia causes acute tubular necrosis with granular casts, so pressure is lowered gradually."]],
  ["CA-644","ASSOCIATION","Anatomy","Biventricular pacemaker: the LV lead runs in which groove?","Atrioventricular groove",["Interventricular groove","Interatrial groove","Terminal sulcus"],["The left ventricular lead of a biventricular pacemaker is placed through the coronary sinus.","The coronary sinus runs in the posterior atrioventricular (coronary) groove.","From there the lead enters a lateral cardiac vein over the left ventricle."]],
  ["CA-645","ASSOCIATION","Valves & endocarditis","Young woman with weeks of fatigue and linear red-brown streaks under her nails — next useful exam","Cardiac auscultation",["Fundoscopy","Joint examination","Lymph node exam"],["Splinter hemorrhages are a sign of infective endocarditis.","Endocarditis often damages a valve, causing a new regurgitant murmur.","Other signs are Janeway lesions, Osler nodes and Roth spots."]],
  ["CA-646","SIDE_EFFECT","Valves & endocarditis","Weeks after a pacemaker: leg swelling, pulsating tender liver and clear lungs","Tricuspid regurgitation",["Mitral regurgitation","Aortic regurgitation","Pulmonic stenosis"],["A lead crossing the tricuspid valve can damage it or stop it closing.","Tricuspid regurgitation causes right-sided failure without pulmonary congestion.","A pulsatile liver comes from systolic backflow into the hepatic veins."]],
  ["CA-647","SIDE_EFFECT","Cardiac drugs","Exertional angina; isosorbide dinitrate is planned — most likely side effect","Throbbing headache",["Dry cough","Ankle edema","Constipation"],["Nitrates dilate vessels throughout the body.","Meningeal vasodilation causes a throbbing headache.","Other effects are flushing, orthostatic hypotension and reflex tachycardia."]],
  ["CA-648","ASSOCIATION","Vascular disease","High-speed head-on crash, widened mediastinum, then PEA arrest — site of aortic injury","Aortic isthmus",["Ascending aorta","Aortic root","Abdominal aorta"],["Rapid deceleration shears the aorta at its fixed point.","The isthmus, just distal to the left subclavian at the ligamentum arteriosum, is tethered.","Most blunt aortic injuries occur there, and rupture is often fatal."]],
  ["CA-649","ASSOCIATION","Valves & endocarditis","Elderly man with exertional dyspnea, harsh murmur to the neck, soft S2 and an S4","Calcified valve with stiff leaflets",["Fused commissures with thick chordae","Floppy leaflets that prolapse","Dilated root with normal leaflets"],["Aortic stenosis in the elderly is usually calcific degeneration of a tricuspid valve.","Calcium deposits stiffen the leaflets, restricting opening.","A soft or absent A2 signals severe stenosis."]],
  ["CA-650","ASSOCIATION","Valves & endocarditis","Mitral regurgitation murmur radiating to the axilla — best sign of severity","An audible S3",["A loud S1","Murmur intensity","An opening snap"],["Severe mitral regurgitation returns a large volume to the ventricle in diastole.","Rapid filling of the volume-overloaded ventricle produces an S3.","Murmur loudness correlates poorly with severity."]],
  ["CA-651","MECHANISM","Cardiac physiology","Trauma creates an arteriovenous fistula — change in the LV pressure–volume loop","Preload up, afterload down, SV up",["Preload down, afterload up, SV down","Preload up, afterload up, SV down","Preload down, afterload down, SV up"],["A fistula lets arterial blood bypass the arterioles and return quickly to the veins.","Afterload falls and venous return rises.","The loop widens to the right with a higher stroke volume; contractility is unchanged at first."]],
  ["CA-652","ASSOCIATION","Valves & endocarditis","Mitral stenosis with hemoptysis — finding suggesting additional aortic valve disease","Raised LV diastolic pressure",["Raised left atrial pressure","Raised pulmonary artery pressure","Raised right atrial pressure"],["Mitral stenosis protects the left ventricle, keeping its diastolic pressure normal or low.","Aortic regurgitation or stenosis raises LV diastolic pressure.","A high LV diastolic pressure therefore suggests coexisting aortic disease."]],
  ["CA-653","ASSOCIATION","Cardiomyopathy & tumors","Young man with heart failure two weeks after a viral illness — echo finding","Dilated ventricles, poor systolic function",["Thick walls, small cavity, good function","Normal walls, stiff and restrictive","Normal ventricles, thick pericardium"],["Viral myocarditis, often coxsackie B, can lead to dilated cardiomyopathy.","Echo shows dilated chambers with reduced ejection fraction.","Many patients recover, but some progress to chronic heart failure."]],
  ["CA-654","SIDE_EFFECT","Cardiac drugs","Took nitroglycerin for chest pain while on tadalafil; BP 50/20 — cellular cause","cGMP buildup",["cAMP buildup","IP₃ buildup","Calcium buildup"],["Nitrates raise cGMP by releasing nitric oxide.","PDE-5 inhibitors stop cGMP from being broken down.","Together they cause massive vasodilation and life-threatening hypotension."]],
  ["CA-655","MECHANISM","Cardiac drugs","Nonischemic cardiomyopathy, EF 30% — diuretic that improves survival","Spironolactone",["Furosemide","Hydrochlorothiazide","Acetazolamide"],["Mineralocorticoid receptor antagonists reduce mortality in HFrEF.","They block aldosterone-driven fibrosis, sodium retention and potassium loss.","Potassium and renal function must be monitored; spironolactone can cause gynecomastia."]],
  ["CA-656","SIDE_EFFECT","Cardiomyopathy & tumors","Breast cancer on trastuzumab; EF falls to 40% — expected cardiac pathology","Weaker contraction, no fibrosis",["Myocyte necrosis with fibrosis","Amyloid between myocytes","Lymphocytic myocarditis"],["Trastuzumab blocks HER2, which helps myocytes survive stress.","It causes reversible dysfunction without cell death or scarring.","Function usually recovers after stopping the drug, unlike anthracycline toxicity."]],
  ["CA-657","ASSOCIATION","Valves & endocarditis","Infant autopsy incidentally finds a bicuspid aortic valve — later risk","Aortic stenosis in midlife",["Mitral stenosis in childhood","Aortic dissection in childhood","Pulmonic stenosis in midlife"],["A bicuspid aortic valve is the commonest congenital heart defect.","Abnormal flow causes early calcification and stenosis, often in the 50s.","It is also associated with aortic dilation, regurgitation and coarctation."]],
  ["CA-658","ASSOCIATION","Cardiomyopathy & tumors","Teen dies jogging; uncle died young; asymmetric septal hypertrophy — mutated protein","β-myosin heavy chain",["Dystrophin","Fibrillin-1","Titin"],["Hypertrophic cardiomyopathy is the commonest cause of sudden death in young athletes.","Most cases are autosomal dominant mutations in sarcomere genes.","β-myosin heavy chain and myosin-binding protein C are the most frequent."]],
  ["CA-659","MECHANISM","Cardiac drugs","Late-presenting anterior MI with apical akinesia, EF 38% — long-term benefit of an ACE inhibitor","Limits LV dilation",["Restores dead myocytes","Dissolves the coronary clot","Raises contractility"],["After a large MI, the ventricle remodels and dilates.","Angiotensin II drives hypertrophy, fibrosis and dilation.","ACE inhibitors limit remodelling and improve survival."]],
  ["CA-660","ASSOCIATION","Cardiomyopathy & tumors","Young man dies suddenly after a week of chest discomfort; myocyte necrosis with a dense mononuclear infiltrate","Acute myocarditis",["Acute myocardial infarction","Hypertrophic cardiomyopathy","Cardiac sarcoidosis"],["Myocarditis shows inflammatory cells, mainly lymphocytes, with myocyte necrosis.","Viruses such as coxsackie B are the commonest cause.","It can cause arrhythmias and sudden death in young adults."]],
  ["CA-661","ASSOCIATION","Ischemic heart disease","Dies 2 hours after LAD occlusion — light microscopy of the affected muscle","Normal-appearing myocardium",["Coagulative necrosis","Neutrophil infiltrate","Granulation tissue"],["Light microscopic changes of infarction appear after about 4 hours.","Early changes are wavy fibres and contraction band necrosis.","Before that, only electron microscopy or special stains show injury."]],
  ["CA-662","MECHANISM","Cardiac drugs","Digoxin added to metoprolol slows his atrial fibrillation rate — explanation","More parasympathetic tone",["More sympathetic tone","Blocked AV node Ca²⁺ channels","Shorter AV node refractoriness"],["Digoxin increases vagal tone.","Vagal tone slows AV nodal conduction.","Fewer atrial impulses reach the ventricles, lowering the resting ventricular rate."]],
  ["CA-663","ASSOCIATION","Hypertension","Autopsy after a crash shows a big left atrium, increased LV mass and thick LV walls","Long-standing hypertension",["Chronic aortic regurgitation","Dilated cardiomyopathy","Endurance athletic training"],["Pressure overload from hypertension causes concentric hypertrophy.","Sarcomeres are added in parallel, thickening the walls.","A stiff ventricle raises filling pressure, enlarging the left atrium."]],
  ["CA-664","ASSOCIATION","Congenital & fetal","Newborn murmur that is systolic, then continuous, then gone at 24 hours — what happened?","Closure of an arterial left-to-right shunt",["Closure of an atrial right-to-left shunt","Opening of the foramen ovale","Fall in systemic resistance"],["After birth, pulmonary resistance falls and flow across the ductus arteriosus reverses to left-to-right.","As the ductus narrows, it produces a transient murmur.","Functional closure within 24 to 48 hours makes the murmur disappear."]],
  ["CA-665","MECHANISM","Arrhythmias","Atrial flutter at 300/min with a ventricular rate of 150 — what explains the difference?","Calcium current in the AV node",["Sodium current in the AV node","Potassium current in the atria","Funny current in the SA node"],["AV nodal cells depolarise with slow L-type calcium currents.","Their slow recovery gives the node a long refractory period.","The node blocks every other flutter wave, producing 2:1 conduction."]],
  ["CA-666","MECHANISM","Cardiac physiology","Before myocyte relaxation, cytoplasmic calcium falls rapidly — which protein helps?","Sodium–calcium exchanger",["Ryanodine receptor","L-type calcium channel","Troponin C"],["Relaxation needs calcium removed from the cytoplasm.","SERCA pumps calcium back into the sarcoplasmic reticulum.","The sodium–calcium exchanger pumps calcium out of the cell."]],
  ["CA-667","MECHANISM","Heart failure & shock","Worsening dyspnea with crackles and a high BNP — main trigger for BNP release","Higher ventricular wall stress",["Higher arterial pressure","Lower plasma sodium","Higher sympathetic tone"],["BNP is made by ventricular myocytes.","It is released when volume overload stretches the ventricular walls.","BNP promotes natriuresis and vasodilation; a low level helps exclude heart failure."]],
  ["CA-668","ASSOCIATION","Vascular disease","Young heavy smoker with painful fingertip ulcers and superficial thrombophlebitis — vessel pathology","Segmental vasculitis into veins and nerves",["Granulomas in large arteries","Fibrinoid necrosis of small vessels","Lipid-filled intimal plaques"],["Thromboangiitis obliterans (Buerger disease) affects young male smokers.","It is a segmental thrombosing vasculitis that extends to nearby veins and nerves.","Smoking cessation is the only effective treatment."]],
  ["CA-669","ASSOCIATION","Pericardium","Driver hits the steering wheel; falling BP, tachycardia, distended neck veins, normal breath sounds","Cardiac tamponade",["Tension pneumothorax","Aortic rupture","Hemorrhagic shock"],["Blunt chest trauma can bleed into the pericardium.","Rising pericardial pressure restricts filling, distending the neck veins.","Normal breath sounds argue against tension pneumothorax."]],
  ["CA-670","MECHANISM","Heart failure & shock","Ascites after a pulmonary embolism caused right heart failure — portal oncotic, hydrostatic, permeability","Normal, high, normal",["Low, high, normal","Normal, normal, high","Low, normal, high"],["Right heart failure raises central venous pressure.","Pressure backs up through the hepatic veins into the liver sinusoids.","Higher capillary hydrostatic pressure pushes fluid into the abdomen."]],
  ["CA-671","ASSOCIATION","Ischemic heart disease","Anterior wall hypokinesis with EF 35% fully recovers 10 days after CABG","Hibernating myocardium",["Stunned myocardium","Myocardial infarction","Ventricular remodelling"],["Hibernating myocardium is chronically underperfused but alive.","It down-regulates contraction to survive.","Restoring blood flow recovers function; stunning follows a brief, restored ischemia."]],
  ["CA-672","MECHANISM","Cardiac drugs","Neprilysin inhibitor prolongs endogenous polypeptides — which cells secrete them?","Cardiomyocytes",["Juxtaglomerular cells","Endothelial cells","Adrenal cortex cells"],["Natriuretic peptides are secreted by atrial and ventricular myocytes.","Neprilysin normally breaks them down.","Sacubitril blocks neprilysin, prolonging their natriuretic and vasodilating effects."]],
  ["CA-673","ASSOCIATION","Cardiomyopathy & tumors","Young man dies in sleep; huge heart with an LV mural thrombus and minor coronary disease; father died young","Dilated cardiomyopathy",["Hypertrophic cardiomyopathy","Ischemic cardiomyopathy","Restrictive cardiomyopathy"],["A grossly dilated heart with little coronary disease is dilated cardiomyopathy.","Stasis in the weak ventricle leads to mural thrombus.","About a third of cases are familial, often autosomal dominant."]],
  ["CA-674","ASSOCIATION","Cardiac physiology","Decompensated heart failure with a low-pitched sound just after S2 at the apex — reflects","Higher LV end-systolic volume",["Lower LV end-diastolic volume","Higher LV wall stiffness","Stenotic mitral valve"],["The S3 is produced by rapid filling into a dilated, volume-overloaded ventricle.","A failing ventricle empties poorly, so end-systolic volume is high.","An S3 in older adults strongly suggests heart failure."]],
  ["CA-675","ASSOCIATION","Valves & endocarditis","Tall young man with myopia, long fingers and a late systolic apical murmur — cause of the murmur","Myxomatous mitral degeneration",["Rheumatic mitral scarring","Calcified mitral annulus","Papillary muscle ischemia"],["Marfan syndrome causes myxomatous degeneration of connective tissue.","The mitral leaflets become floppy and prolapse.","Prolapse causes a midsystolic click and late systolic regurgitant murmur."]],
  ["CA-676","ASSOCIATION","Vascular disease","Smoker with thigh cramps after one block, relieved by rest — cause","Lipid-filled intimal plaques",["Inflamed vessel walls","Venous valve failure","Nerve root compression"],["Exertional leg pain relieved by rest is intermittent claudication.","Atherosclerotic plaques narrow the iliac or femoral arteries.","Smoking and diabetes are the strongest risk factors for peripheral artery disease."]],
  ["CA-677","SIDE_EFFECT","Cardiac drugs","Acute MI with severe heart failure; dobutamine is started — which value will rise?","Myocardial oxygen consumption",["Systemic vascular resistance","Ventricular end-diastolic volume","Diastolic filling time"],["Dobutamine stimulates β1 receptors, raising contractility and heart rate.","More work means more myocardial oxygen consumption.","In ischemia this can worsen the infarct, so it is used with care."]],
  ["CA-678","MECHANISM","Ischemic heart disease","LAD and circumflex plaques — growth factors driving lesion growth came from","Platelets",["Neutrophils","Hepatocytes","Fibroblasts"],["Platelets adhere at sites of endothelial injury.","They release platelet-derived growth factor (PDGF).","PDGF draws smooth muscle cells into the intima, where they proliferate and lay down matrix."]],
  ["CA-679","ASSOCIATION","Ischemic heart disease","Hypotension, HR 48 and ST elevation in II, III and aVF — which artery?","Right coronary",["Left anterior descending","Left circumflex","Left main"],["ST elevation in II, III and aVF is an inferior MI.","The RCA supplies the inferior wall and usually the SA and AV nodes.","Bradycardia and hypotension are common with RCA occlusion."]],
  ["CA-680","ASSOCIATION","Ischemic heart disease","New systolic murmur during an MI that vanishes after the artery is reopened — source","Papillary muscle",["Mitral valve leaflet","Aortic valve cusp","Interventricular septum"],["Ischemia makes a papillary muscle stop contracting.","The leaflet is no longer held, so transient mitral regurgitation appears.","Restoring flow restores papillary function, and the murmur disappears."]],
  ["CA-681","MECHANISM","Cardiac drugs","Infusion in an EP study raises contractility and lowers vascular resistance","Isoproterenol",["Phenylephrine","Norepinephrine","Dopamine"],["Isoproterenol is a nonselective β agonist.","β1 raises heart rate and contractility; β2 dilates muscle vessels, lowering SVR.","It is used in EP studies to provoke arrhythmias."]],
  ["CA-682","ASSOCIATION","Hypertension","Weight loss, tremor, diffuse goiter and exophthalmos — which value is decreased?","Systemic vascular resistance",["Cardiac output","Heart rate","Pulse pressure"],["Thyroid hormone raises metabolism and heat production.","Peripheral vessels dilate to release heat, lowering systemic vascular resistance.","Cardiac output, heart rate and pulse pressure all rise."]],
  ["CA-683","ASSOCIATION","Congenital & fetal","One-week-old with a new holosystolic murmur at the left mid-to-lower sternal border","Underdeveloped interventricular septum",["Failed fusion of endocardial cushions","Failed spiralling of the septum","Excess resorption of septum primum"],["A holosystolic murmur at the lower left sternal border is a VSD.","It is often not heard at birth because pulmonary resistance is still high.","Most are membranous defects, and many small ones close spontaneously."]],
  ["CA-684","ASSOCIATION","Heart failure & shock","Lateral STEMI with hypotension and cold, clammy limbs — contractility, SVR, PA pressure","Contractility ↓, SVR ↑, PA pressure ↑",["Contractility ↓, SVR ↓, PA pressure ↓","Contractility ↑, SVR ↓, PA pressure ↑","Contractility ↓, SVR ↑, PA pressure ↓"],["Cardiogenic shock comes from loss of contracting muscle.","Low output triggers vasoconstriction, raising SVR and causing cold extremities.","Blood backs up into the lungs, raising pulmonary pressures."]],
  ["CA-685","MECHANISM","Ischemic heart disease","Multivessel coronary disease — which cell was involved in the very first step?","Endothelial cells",["Smooth muscle cells","Macrophages","T lymphocytes"],["Atherosclerosis begins with endothelial injury or dysfunction.","Damaged endothelium lets LDL in and expresses adhesion molecules.","Monocytes then enter, become macrophages and form foam cells."]],
  ["CA-686","ASSOCIATION","Valves & endocarditis","Decompensated heart failure with an apical holosystolic murmur that disappears after diuresis","Secondary mitral regurgitation",["Primary mitral regurgitation","Papillary muscle rupture","Mitral valve prolapse"],["A dilated ventricle pulls the papillary muscles apart and stretches the annulus.","The normal leaflets fail to meet, causing secondary (functional) regurgitation.","Diuretics and vasodilators shrink the ventricle, and the regurgitation improves."]],
  ["CA-687","ASSOCIATION","Hypertension","Dies of heart failure; uniformly thick LV walls, small cavity, big dark myocyte nuclei","Hypertensive heart disease",["Hypertrophic cardiomyopathy","Dilated cardiomyopathy","Cardiac amyloidosis"],["Chronic hypertension causes concentric left ventricular hypertrophy.","Myocytes enlarge with large, boxcar-like hyperchromatic nuclei.","Interstitial fibrosis develops, and diastolic dysfunction leads to heart failure."]],
  ["CA-688","MECHANISM","Cardiac drugs","Norepinephrine for shock raises BP while heart rate falls slightly — receptors responsible","α1 receptors in vessels",["β1 receptors in the heart","β2 receptors in vessels","M2 receptors in the heart"],["Norepinephrine strongly stimulates α1 receptors, raising vascular resistance.","The rise in blood pressure activates the baroreflex.","Reflex vagal tone overrides its weaker β1 effect, so heart rate dips."]],
  ["CA-689","ASSOCIATION","Ischemic heart disease","LAD tied off in an experiment — how soon does affected muscle stop contracting?","About 1 minute",["About 5 minutes","About 20 minutes","About 1 hour"],["Myocytes have little stored oxygen and ATP.","Contraction stops within about 60 seconds of total ischemia.","Irreversible injury begins after about 20 to 30 minutes."]],
  ["CA-690","ASSOCIATION","Valves & endocarditis","Childhood rheumatic fever; high-pitched diastolic sound then a rumble at the apex — when is the sound?","Mitral valve opening",["Aortic valve closing","Mitral valve closing","Tricuspid valve opening"],["The opening snap is the stiff mitral valve popping open.","It occurs early in diastole, after S2.","It is followed by the rumbling diastolic murmur of mitral stenosis."]],
  ["CA-691","MECHANISM","Cardiac physiology","EDV 125 mL and ESV 75 mL — which statement is true?","Ejection fraction is 40%",["Stroke volume is 75 mL","Ejection fraction is 60%","Stroke volume is 200 mL"],["Stroke volume = end-diastolic volume − end-systolic volume = 50 mL.","Ejection fraction = stroke volume ÷ end-diastolic volume = 40%.","An EF of 40% or less is heart failure with reduced ejection fraction."]],
  ["CA-692","ASSOCIATION","Hypertension","Extreme BP with papilledema, rising creatinine and schistocytes — renal arteriole finding","Fibrinoid necrosis of arteriole walls",["Hyaline thickening of arterioles","Plaque in the main renal artery","Granulomas in arteriole walls"],["Hypertensive emergency causes malignant nephrosclerosis.","Arterioles show fibrinoid necrosis and onion-skin hyperplasia.","Red cells shear on damaged vessels, causing microangiopathic hemolysis."]],
  ["CA-693","MECHANISM","Hypertension","Elderly heart with concentric LVH and enlarged myocytes — which substance contributed?","Angiotensin II",["Nitric oxide","Natriuretic peptide","Prostacyclin"],["Angiotensin II acts directly on myocytes to stimulate hypertrophy.","It also promotes fibroblast activity and fibrosis.","ACE inhibitors and ARBs can reverse hypertrophy."]],
  ["CA-694","ASSOCIATION","Heart failure & shock","HFpEF with concentric LVH — compliance, angiotensin II and β-myosin heavy chain","Compliance ↓, Ang II ↑, β-MHC ↑",["Compliance ↑, Ang II ↓, β-MHC ↓","Compliance ↓, Ang II ↓, β-MHC ↓","Compliance ↑, Ang II ↑, β-MHC ↑"],["Concentric hypertrophy stiffens the ventricle, lowering compliance.","Angiotensin II signalling drives the hypertrophy and fibrosis.","Stressed myocytes switch to fetal gene expression, including β-myosin heavy chain."]],
  ["CA-695","ASSOCIATION","Anatomy","Heavy smoker with hemoptysis and swelling of the right face and arm only — blocked vein","Right brachiocephalic",["Superior vena cava","Right subclavian","Right internal jugular"],["The right brachiocephalic vein drains the right arm, head and neck.","A blockage swells the face and arm on that side only.","SVC obstruction affects both sides; lung cancer is a common cause."]],
  ["CA-696","MECHANISM","Valves & endocarditis","Fever a month after mitral valve replacement; gram-positive, catalase+, coagulase− cocci — empiric drug","Vancomycin",["Nafcillin","Ceftriaxone","Penicillin G"],["Coagulase-negative staphylococci (S. epidermidis) cause early prosthetic valve endocarditis.","They form biofilms on devices and are often methicillin resistant.","Empiric therapy includes vancomycin, with rifampin and gentamicin for prosthetic valves."]],
];
